<#
.SYNOPSIS
    Every privileged Azure RBAC and Entra ID role assignment in your tenant, scored, in one HTML report.

.DESCRIPTION
    One file, nothing to install. Sign in, read, get a report you can hand to someone.

    Finds what the portal and posture tools do not put in one place: custom roles rated by the actions
    they really grant after NotActions, privilege inherited through nested groups with every member
    named, app registrations holding privileged roles with no valid credential, disabled users with
    permanent assignments, and PIM eligible and activated assignments next to permanent ones.

    Read-only. It signs in with read scopes, reads, and writes an HTML file. It changes nothing.

    To act on the findings rather than just read them, use the module. It returns the findings as
    objects and can remove an assignment with a prompt, a JSON backup and a refusal for anything
    inherited through a group, held in PIM, named as break-glass or belonging to you:

        Install-Module RiskyRolesAnalyzer -AllowPrerelease
        https://github.com/simon-vedder/risky-roles-analyzer

.PARAMETER OutputPath
    Where to write the report. Default: ./RiskyRolesAnalyzer-report-<timestamp>.html

.PARAMETER TenantId
    Tenant to sign in to. Without it the sign-in picks your home tenant.

.PARAMETER SubscriptionId
    Limit the Azure part to these subscriptions. Without it, every enabled subscription in the tenant.

.PARAMETER AdditionalAzureRole
    Azure role names to treat as privileged on top of the built-in list.

.PARAMETER AdditionalEntraRole
    Entra role names to treat as privileged on top of the built-in list.

.PARAMETER BreakGlassAccount
    UPNs or object ids of emergency access accounts. They are still reported, and marked so nobody
    acts on them by mistake.

.PARAMETER MinimumSeverity
    Drop findings below this severity. Default Info, which keeps everything.

.PARAMETER SkipAzure
    Entra ID only. No Azure sign-in, no Azure RBAC.

.PARAMETER SkipEntra
    Azure RBAC only.

.PARAMETER SkipPim
    Do not read PIM eligibility. Use it on tenants without Entra ID P2 to silence the warning.

.PARAMETER UseDeviceCode
    Device code sign-in, for hosts without a browser.

.PARAMETER NoOpen
    Do not open the report when it is written.

.EXAMPLE
    ./Invoke-RiskyRolesAudit.ps1

.EXAMPLE
    ./Invoke-RiskyRolesAudit.ps1 -BreakGlassAccount 'breakglass@contoso.com' -MinimumSeverity High

.EXAMPLE
    ./Invoke-RiskyRolesAudit.ps1 -SkipAzure -SkipPim -OutputPath ./entra.html

.NOTES
    Generated from the RiskyRolesAnalyzer module 0.1.0-preview by tools/Build-StandaloneScript.ps1.
    Do not edit this file: change the module and rebuild, or the next build overwrites you.

    Requires PowerShell 7.2+ and the modules Az.Accounts, Az.Resources and
    Microsoft.Graph.Authentication. Install them once with:

        Install-Module Az.Accounts, Az.Resources, Microsoft.Graph.Authentication -Scope CurrentUser

    Required permissions: Azure Reader on the subscriptions you audit; Graph delegated scopes
    RoleManagement.Read.Directory, Directory.Read.All, Group.Read.All and Application.Read.All,
    which you consent to at sign-in. Entra ID P2 for the PIM parts.

    MIT licensed. https://github.com/simon-vedder/risky-roles-analyzer
#>
[CmdletBinding()]
param(
    [Parameter()]
    [string]$OutputPath,

    [Parameter()]
    [string]$TenantId,

    [Parameter()]
    [string[]]$SubscriptionId,

    [Parameter()]
    [string[]]$AdditionalAzureRole,

    [Parameter()]
    [string[]]$AdditionalEntraRole,

    [Parameter()]
    [string[]]$BreakGlassAccount,

    [Parameter()]
    [ValidateSet('Info', 'Low', 'Medium', 'High', 'Critical')]
    [string]$MinimumSeverity = 'Info',

    [Parameter()]
    [switch]$SkipAzure,

    [Parameter()]
    [switch]$SkipEntra,

    [Parameter()]
    [switch]$SkipPim,

    [Parameter()]
    [switch]$UseDeviceCode,

    [Parameter()]
    [switch]$NoOpen
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

# ================================================================================================
#  Generated file. Everything below comes from the module sources; edit those, then rebuild with
#  tools/Build-StandaloneScript.ps1. The module is the tested version: 144 Pester tests run against
#  a synthetic tenant, and the rules here are the same functions.
# ================================================================================================

$script:ModuleVersion = '0.1.0-preview'
$script:TypeName = @{
    Finding = 'RiskyRolesAnalyzer.RiskyRoleAssignment'
    Removal = 'RiskyRolesAnalyzer.RiskyRoleAssignmentRemoval'
    Restore = 'RiskyRolesAnalyzer.RiskyRoleAssignmentRestore'
}

# ---- Role lists, risky actions and scoring weights (RiskyRoleCatalog.psd1) ----------------------
$script:Catalog = @{
    # Built-in Azure RBAC roles that are treated as privileged. Extend at run time with
    # Get-RiskyRoleAssignment -AdditionalAzureRole.
    PrivilegedAzureRoles = @(
        'Owner'
        'Contributor'
        'User Access Administrator'
        'Role Based Access Control Administrator'
        'Access Review Operator Service Role'
        'Reservation Purchaser'
        'Key Vault Administrator'
        'Storage Account Key Operator Service Role'
        # BloodHound "Dangerous Managed Roles"
        'Security Admin'
        'Resource Policy Contributor'
        # BloodHound "Transitive Managed Identity Access"
        'Virtual Machine Contributor'
        'Website Contributor'
        'Managed Identity Operator'
    )

    # Built-in Entra directory roles that are treated as privileged. Extend with -AdditionalEntraRole.
    PrivilegedEntraRoles = @(
        'Global Administrator'
        'Privileged Role Administrator'
        'Privileged Authentication Administrator'
        'User Administrator'
        'Application Administrator'
        'Cloud Application Administrator'
        'Authentication Administrator'
        'Conditional Access Administrator'
        'Security Administrator'
        'Exchange Administrator'
        'SharePoint Administrator'
        'Intune Administrator'
        'Helpdesk Administrator'
        'Hybrid Identity Administrator'
        'Domain Name Administrator'
        'External Identity Provider Administrator'
        'Partner Tier1 Support'
        'Partner Tier2 Support'
        'Directory Writers'
        'Groups Administrator'
    )

    # Actions that make a custom Azure RBAC role privileged. Matched against the role's Actions and
    # DataActions with wildcard support ("Microsoft.Authorization/*" grants roleAssignments/write),
    # then reduced by NotActions and NotDataActions.
    RiskyAzureActions = @(
        'Microsoft.Authorization/roleAssignments/write'
        'Microsoft.Authorization/roleAssignments/delete'
        'Microsoft.Authorization/denyAssignments/delete'
        'Microsoft.Authorization/roleDefinitions/write'
        'Microsoft.Authorization/roleDefinitions/delete'
        'Microsoft.Authorization/elevateAccess/action'
        'Microsoft.Authorization/policyAssignments/write'
        'Microsoft.Authorization/policyDefinitions/write'
        'Microsoft.ManagedIdentity/userAssignedIdentities/assign/action'
        'Microsoft.Compute/virtualMachines/runCommand/action'
        'Microsoft.Compute/virtualMachines/extensions/write'
        'Microsoft.KeyVault/vaults/accessPolicies/write'
        'Microsoft.Web/sites/publish/Action'
        'Microsoft.Web/sites/config/list/action'
    )

    # Resource actions that make a custom Entra directory role privileged.
    RiskyEntraActions = @(
        'microsoft.directory/users/create'
        'microsoft.directory/users/inviteGuest'
        'microsoft.directory/users/password/update'
        'microsoft.directory/users/authenticationMethods/update'
        'microsoft.directory/servicePrincipals/create'
        'microsoft.directory/servicePrincipals/credentials/update'
        'microsoft.directory/applications/create'
        'microsoft.directory/applications/credentials/update'
        'microsoft.directory/applications/owners/update'
        'microsoft.directory/groups/members/update'
        'microsoft.directory/roleAssignments/allProperties/allTasks'
        'microsoft.directory/roleDefinitions/allProperties/allTasks'
    )

    # Scoring. A 0.0 to 10.0 score: base per role, multiplied by scope breadth, then modified by
    # assignment type, principal type and whether the principal can sign in at all.
    Scoring              = @{
        DefaultBase       = 3.0
        CustomRoleBase    = 6.0
        CriticalRoleBase  = 9.0
        HighRoleBase      = 7.0
        MediumRoleBase    = 5.5
        CriticalRoles     = @(
            'Owner', 'User Access Administrator', 'Role Based Access Control Administrator'
            'Global Administrator', 'Privileged Role Administrator', 'Privileged Authentication Administrator'
        )
        HighRoles         = @(
            'Contributor', 'Security Admin', 'Security Administrator'
            'Application Administrator', 'Cloud Application Administrator'
            'Authentication Administrator', 'User Administrator'
            'Key Vault Administrator', 'Resource Policy Contributor'
        )
        MediumRoles       = @(
            'Virtual Machine Contributor', 'Website Contributor', 'Managed Identity Operator'
            'Conditional Access Administrator', 'Exchange Administrator'
            'SharePoint Administrator', 'Intune Administrator'
            'Helpdesk Administrator', 'Hybrid Identity Administrator'
            'Domain Name Administrator', 'External Identity Provider Administrator'
            'Groups Administrator', 'Directory Writers'
            'Partner Tier1 Support', 'Partner Tier2 Support'
            'Storage Account Key Operator Service Role'
            'Access Review Operator Service Role', 'Reservation Purchaser'
        )
        # A custom role that grants one of these is rated like a critical built-in role.
        CriticalActions   = @(
            'Microsoft.Authorization/roleAssignments/write'
            'Microsoft.Authorization/roleDefinitions/write'
            'Microsoft.Authorization/elevateAccess/action'
            'Microsoft.Authorization/denyAssignments/delete'
            'microsoft.directory/roleAssignments/allProperties/allTasks'
            'microsoft.directory/roleDefinitions/allProperties/allTasks'
            'microsoft.directory/users/password/update'
            'microsoft.directory/applications/credentials/update'
            'microsoft.directory/servicePrincipals/credentials/update'
        )
        StackedActionBonus = 0.5   # three or more risky actions in one custom role
        ScopeMultiplier   = @{
            Root            = 1.0
            Tenant          = 1.0
            ManagementGroup = 0.95
            Subscription    = 0.85
            ResourceGroup   = 0.65
            AdminUnit       = 0.65
            Resource        = 0.45
            Object          = 0.45
            Other           = 0.85
        }
        EligibleModifier  = -1.5   # PIM eligible: has to be activated first
        ApplicationModifier = 0.5  # apps and managed identities are quieter persistence vectors
        ActivityModifier  = @{
            Disabled           = -2.0
            NoValidCredential  = -1.0
            BlockedByMicrosoft = -2.5
        }
        # Severity labels by score, checked from the top.
        Severity          = @(
            @{ Name = 'Critical'; Minimum = 9.0 }
            @{ Name = 'High'; Minimum = 7.0 }
            @{ Name = 'Medium'; Minimum = 5.0 }
            @{ Name = 'Low'; Minimum = 3.0 }
            @{ Name = 'Info'; Minimum = 0.0 }
        )
    }

    # Names that usually mean an emergency access account. Only a hint: the module protects what
    # -BreakGlassAccount names, and warns when an unprotected principal matches this pattern.
    BreakGlassNamePattern = '(?i)break.?glass|emergency.?access|^bg[-_ ]?\d|^emergency'

    # Graph scopes. The read set is what Get-RiskyRoleAssignment needs; the write scope is only
    # requested with Connect-RiskyRolesAnalyzer -RequestWriteScopes and only used by Remove-.
    GraphScopes          = @{
        Read  = @('RoleManagement.Read.Directory', 'Directory.Read.All', 'Group.Read.All', 'Application.Read.All')
        Write = @('RoleManagement.ReadWrite.Directory')
    }
}

# ---- The HTML report template (Resources/report.html) -------------------------------------------
$script:ReportTemplate = @'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>__TITLE__</title>
<style>
  :root {
    --bg: #0f172a; --panel: #1e293b; --panel2: #273449; --border: #334155;
    --text: #e2e8f0; --muted: #94a3b8; --accent: #38bdf8; --ok: #22c55e; --warn: #f59e0b; --err: #ef4444;
  }
  * { box-sizing: border-box; }
  body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background: var(--bg); color: var(--text); font-size: 14px; line-height: 1.5; }
  header { padding: 24px 32px; border-bottom: 1px solid var(--border); background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%); display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; flex-wrap: wrap; }
  h1 { margin: 0 0 4px 0; font-size: 22px; font-weight: 600; letter-spacing: -0.2px; }
  .subtitle { color: var(--muted); font-size: 13px; }
  .eyebrow { font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: var(--accent); font-weight: 700; margin-bottom: 6px; }
  .summary { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; padding: 20px 32px; border-bottom: 1px solid var(--border); }
  .stat { background: var(--panel); border: 1px solid var(--border); border-radius: 8px; padding: 14px 16px; }
  .stat-label { font-size: 11px; text-transform: uppercase; color: var(--muted); letter-spacing: 0.5px; }
  .stat-value { font-size: 22px; font-weight: 600; margin-top: 4px; }
  .controls { display: flex; flex-wrap: wrap; gap: 10px; padding: 16px 32px; border-bottom: 1px solid var(--border); background: var(--panel); align-items: center; }
  .controls input, .controls select, .controls button { background: var(--panel2); color: var(--text); border: 1px solid var(--border); border-radius: 6px; padding: 7px 11px; font-size: 13px; font-family: inherit; }
  .controls input { min-width: 240px; }
  .controls input:focus, .controls select:focus { outline: none; border-color: var(--accent); }
  .controls button { cursor: pointer; font-weight: 500; }
  .controls button:hover { background: var(--panel); }
  .controls button.primary { background: var(--accent); color: #0f172a; border-color: var(--accent); font-weight: 600; }
  .controls button.primary:hover { background: #0ea5e9; }
  .controls button.primary:disabled { opacity: 0.4; cursor: not-allowed; }
  .toggle-btn[data-active="true"] { background: var(--accent) !important; color: #0f172a !important; border-color: var(--accent) !important; font-weight: 600 !important; }
  .controls .count { margin-left: auto; color: var(--muted); font-size: 12px; }
  .selection-bar { display: flex; gap: 10px; padding: 10px 32px; border-bottom: 1px solid var(--border); background: rgba(56,189,248,0.06); align-items: center; font-size: 12px; color: var(--muted); flex-wrap: wrap; }
  .selection-bar button { background: var(--panel2); color: var(--text); border: 1px solid var(--border); border-radius: 6px; padding: 5px 10px; font-size: 12px; cursor: pointer; font-family: inherit; }
  .selection-bar button.primary { background: var(--accent); color: #0f172a; border-color: var(--accent); font-weight: 600; }
  .selection-bar button:disabled { opacity: 0.4; cursor: not-allowed; }
  .table-wrap { padding: 0 32px 32px 32px; overflow-x: auto; }
  table { width: 100%; border-collapse: collapse; margin-top: 16px; }
  thead th { text-align: left; padding: 10px 12px; background: var(--panel); border-bottom: 2px solid var(--border); font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.4px; color: var(--muted); cursor: pointer; user-select: none; white-space: nowrap; }
  thead th:hover { color: var(--text); }
  thead th.sorted-asc::after  { content: ' \25B2'; color: var(--accent); }
  thead th.sorted-desc::after { content: ' \25BC'; color: var(--accent); }
  thead th.nosort { cursor: default; }
  tbody td { padding: 9px 12px; border-bottom: 1px solid var(--border); vertical-align: top; }
  tbody tr:hover { background: rgba(56,189,248,0.04); }
  tbody tr.selected { background: rgba(56,189,248,0.10); }
  tr.accepted { opacity: 0.45; }
  tr.accepted td { text-decoration: line-through; text-decoration-color: rgba(148,163,184,0.4); }
  tr.accepted td.select-cell, tr.accepted td.accept-cell { text-decoration: none; }
  .select-cell, .accept-cell { text-align: center; }
  .select-cb, .accept-cb { width: 17px; height: 17px; cursor: pointer; }
  .select-cb { accent-color: var(--accent); }
  .select-cb:disabled { cursor: not-allowed; opacity: 0.35; }
  .accept-cb { accent-color: var(--ok); }
  .badge { display: inline-block; padding: 2px 8px; border-radius: 999px; font-size: 11px; font-weight: 600; border: 1px solid transparent; white-space: nowrap; }
  .badge-User            { background: rgba(96,165,250,0.15);  color: #93c5fd; border-color: rgba(96,165,250,0.4); }
  .badge-Group           { background: rgba(167,139,250,0.15); color: #c4b5fd; border-color: rgba(167,139,250,0.4); }
  .badge-EnterpriseApp, .badge-AppRegistration { background: rgba(244,114,182,0.15); color: #f9a8d4; border-color: rgba(244,114,182,0.4); }
  .badge-ManagedIdentity { background: rgba(251,146,60,0.15);  color: #fdba74; border-color: rgba(251,146,60,0.4); }
  .badge-Other, .badge-Unknown { background: rgba(148,163,184,0.15); color: #cbd5e1; border-color: rgba(148,163,184,0.4); }
  .badge-Permanent       { background: rgba(34,197,94,0.15);   color: #86efac; border-color: rgba(34,197,94,0.4); }
  .badge-Eligible        { background: rgba(245,158,11,0.15);  color: #fcd34d; border-color: rgba(245,158,11,0.4); }
  .badge-Activated       { background: rgba(251,146,60,0.18);  color: #fdba74; border-color: rgba(251,146,60,0.45); }
  .badge-Azure           { background: rgba(56,189,248,0.15);  color: #7dd3fc; border-color: rgba(56,189,248,0.4); }
  .badge-Entra           { background: rgba(129,140,248,0.15); color: #a5b4fc; border-color: rgba(129,140,248,0.4); }
  .badge-status-Active             { background: rgba(34,197,94,0.15); color: #86efac; border-color: rgba(34,197,94,0.4); }
  .badge-status-Disabled           { background: rgba(239,68,68,0.18); color: #fca5a5; border-color: rgba(239,68,68,0.4); }
  .badge-status-NoValidCredential  { background: rgba(245,158,11,0.18); color: #fcd34d; border-color: rgba(245,158,11,0.4); }
  .badge-status-BlockedByMicrosoft { background: rgba(239,68,68,0.25); color: #fecaca; border-color: rgba(239,68,68,0.6); }
  .badge-status-Unknown            { background: rgba(148,163,184,0.15); color: #cbd5e1; border-color: rgba(148,163,184,0.4); }
  .badge-protected { background: rgba(167,139,250,0.15); color: #c4b5fd; border-color: rgba(167,139,250,0.4); }
  .status-reason, .protected-reason { font-size: 11px; color: var(--muted); margin-top: 3px; }
  .mono { font-family: 'SF Mono', Menlo, Consolas, monospace; font-size: 12px; color: var(--muted); }
  .identity-upn { font-size: 11px; margin-top: 2px; color: #cbd5e1; }
  .identity-id  { font-size: 10px; margin-top: 1px; color: var(--muted); opacity: 0.7; }
  .via { font-size: 11px; color: var(--warn); margin-top: 3px; }
  .empty { padding: 60px; text-align: center; color: var(--muted); }
  .report-footer { text-align: center; padding: 20px 32px 28px 32px; color: var(--muted); font-size: 12px; border-top: 1px solid var(--border); margin-top: 8px; }
  .report-footer a { color: var(--accent); text-decoration: none; }
  .report-footer a:hover { text-decoration: underline; }
  .report-footer strong { color: var(--text); font-weight: 600; }
  .custom-flag { display: inline-block; margin-left: 6px; padding: 1px 6px; border-radius: 4px; background: rgba(239,68,68,0.18); color: #fca5a5; border: 1px solid rgba(239,68,68,0.4); font-size: 10px; font-weight: 700; letter-spacing: 0.4px; vertical-align: middle; }
  .actions-cell { max-width: 380px; }
  .action-pill { display: inline-block; padding: 2px 6px; margin: 1px 2px; border-radius: 4px; background: rgba(245,158,11,0.12); border: 1px solid rgba(245,158,11,0.3); color: #fcd34d; font-family: 'SF Mono', Menlo, Consolas, monospace; font-size: 10px; word-break: break-all; }
  .score { display: inline-block; padding: 3px 8px; border-radius: 4px; font-weight: 700; font-size: 10px; letter-spacing: 0.5px; text-align: center; white-space: nowrap; }
  .score-Critical { background: rgba(239,68,68,0.2);  color: #fca5a5; border: 1px solid rgba(239,68,68,0.5); }
  .score-High     { background: rgba(245,158,11,0.18); color: #fcd34d; border: 1px solid rgba(245,158,11,0.45); }
  .score-Medium   { background: rgba(56,189,248,0.15); color: #7dd3fc; border: 1px solid rgba(56,189,248,0.4); }
  .score-Low      { background: rgba(34,197,94,0.15);  color: #86efac; border: 1px solid rgba(34,197,94,0.4); }
  .score-Info     { background: rgba(148,163,184,0.15); color: #cbd5e1; border: 1px solid rgba(148,163,184,0.4); }
  .score-number { font-size: 10px; color: var(--muted); margin-top: 3px; font-family: 'SF Mono', Menlo, Consolas, monospace; }
  .scope-Root, .scope-Tenant, .scope-ManagementGroup { color: #fca5a5; font-weight: 600; }
  .scope-Subscription { color: #fcd34d; font-weight: 600; }
  .scope-ResourceGroup { color: #7dd3fc; }
  .scope-Resource, .scope-Object { color: #86efac; }
  .scope-AdminUnit { color: #c4b5fd; }
  .scope-detail { font-size: 11px; color: var(--muted); margin-top: 2px; }
  .small-btn { background: var(--panel2); color: var(--text); border: 1px solid var(--border); border-radius: 4px; padding: 4px 8px; cursor: pointer; font-size: 11px; font-family: inherit; }
  .small-btn:hover { background: var(--accent); color: #0f172a; border-color: var(--accent); }
  .small-btn.copied { background: var(--ok); color: #0f172a; border-color: var(--ok); }
  .popup { position: fixed; z-index: 1000; background: var(--panel); border: 1px solid var(--border); border-radius: 8px; padding: 14px; box-shadow: 0 10px 40px rgba(0,0,0,0.5); max-width: 720px; width: min(720px, calc(100vw - 40px)); display: none; }
  .popup pre { background: #0a0f1c; border: 1px solid var(--border); border-radius: 4px; padding: 10px; margin: 6px 0; font-size: 11px; overflow-x: auto; color: #e2e8f0; white-space: pre-wrap; word-break: break-all; }
  .popup h4 { margin: 0 0 8px 0; font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.4px; }
  .popup .close { float: right; cursor: pointer; color: var(--muted); padding: 0 4px; }
  .popup .close:hover { color: var(--text); }
  .popup code { background: rgba(56,189,248,0.12); color: #7dd3fc; padding: 1px 5px; border-radius: 3px; font-family: 'SF Mono', Menlo, Consolas, monospace; font-size: 11px; }
  .popup .note { font-size: 12px; color: var(--muted); margin: 4px 0 8px 0; }
  .prereq-box { background: rgba(245,158,11,0.06); border: 1px solid rgba(245,158,11,0.25); border-radius: 6px; padding: 10px 12px; margin-bottom: 14px; font-size: 12px; color: #e2e8f0; }
  .prereq-title { font-size: 10px; color: #fcd34d; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700; margin-bottom: 6px; }
</style>
</head>
<body>
<header>
  <div>
    <div class="eyebrow">RiskyRolesAnalyzer</div>
    <h1 id="title">__TITLE__</h1>
    <div class="subtitle" id="subtitle"></div>
  </div>
  <div class="subtitle" id="legend">Score 0 to 10 expresses live exploitability. Protected rows are reported, never removed by the module.</div>
</header>
<section class="summary" id="summary"></section>
<section class="controls">
  <input type="text" id="search" placeholder="Search anything (name, role, scope, UPN, AppId, Id)...">
  <select id="filterScope">
    <option value="">All sources</option>
    <option value="Azure">Azure RBAC</option>
    <option value="Entra">Entra ID</option>
  </select>
  <select id="filterAssignment">
    <option value="">All assignment types</option>
    <option value="Permanent">Permanent</option>
    <option value="Activated">Activated (PIM)</option>
    <option value="Eligible">Eligible (PIM)</option>
  </select>
  <select id="filterPrincipal">
    <option value="">All principal types</option>
    <option value="User">Users</option>
    <option value="Group">Groups</option>
    <option value="EnterpriseApp">Enterprise Apps</option>
    <option value="AppRegistration">App Registrations</option>
    <option value="ManagedIdentity">Managed Identities</option>
  </select>
  <select id="filterRole"><option value="">All roles</option></select>
  <select id="filterVia">
    <option value="">Direct &amp; via group</option>
    <option value="direct">Direct only</option>
    <option value="group">Via group only</option>
  </select>
  <select id="filterCustom">
    <option value="">Built-in &amp; custom</option>
    <option value="custom">Custom only</option>
    <option value="builtin">Built-in only</option>
  </select>
  <select id="filterStatus">
    <option value="">All activity statuses</option>
    <option value="Active">Active only</option>
    <option value="inactive">Inactive only (disabled / no creds / blocked)</option>
    <option value="Disabled">Disabled</option>
    <option value="NoValidCredential">No valid credential</option>
    <option value="BlockedByMicrosoft">Blocked by Microsoft</option>
  </select>
  <select id="filterSeverity">
    <option value="">Any severity</option>
    <option value="Critical">Critical only</option>
    <option value="High">High &amp; above</option>
    <option value="Medium">Medium &amp; above</option>
    <option value="Low">Low &amp; above</option>
  </select>
  <select id="filterProtected">
    <option value="">Protected &amp; removable</option>
    <option value="removable">Removable only</option>
    <option value="protected">Protected only</option>
  </select>
  <button id="toggleAccepted" class="toggle-btn" data-active="false">Show accepted</button>
  <button id="exportCsv">Export CSV</button>
  <span class="count" id="count"></span>
</section>
<section class="selection-bar">
  <span id="selectionCount">0 selected</span>
  <button id="selectVisible">Select visible</button>
  <button id="clearSelection">Clear</button>
  <button id="copyRemoval" class="primary" disabled>Copy removal command</button>
  <span>The command runs in your PowerShell session, with a prompt and a backup per assignment. Nothing runs from this page.</span>
</section>
<section class="table-wrap">
  <table id="data">
    <thead>
      <tr>
        <th class="nosort" title="Select for the removal command">Select</th>
        <th data-key="RiskScore">Severity</th>
        <th data-key="RoleScope">Source</th>
        <th data-key="RoleName">Role</th>
        <th data-key="AssignmentType">Type</th>
        <th data-key="PrincipalType">Principal</th>
        <th data-key="PrincipalName">Identity</th>
        <th data-key="ActivityStatus">Status</th>
        <th data-key="ScopeLevel">Scope</th>
        <th data-key="ViaGroup">Via</th>
        <th data-key="Protected">Protected</th>
        <th class="nosort">Risky Actions</th>
        <th class="nosort">Cleanup</th>
        <th class="nosort" title="Mark as reviewed; hides the row">Accept</th>
      </tr>
    </thead>
    <tbody></tbody>
  </table>
  <div class="empty" id="empty" style="display:none">No matching findings</div>
</section>
<footer class="report-footer">
  Generated by <strong>RiskyRolesAnalyzer</strong> <span id="version"></span> &nbsp;&middot;&nbsp;
  <a href="https://simonvedder.com/tools/risky-roles-analyzer" target="_blank" rel="noopener">simonvedder.com/tools/risky-roles-analyzer</a>
</footer>
<div id="popup" class="popup">
  <span class="close" id="popupClose">&times;</span>
  <h4 id="popupTitle">Command</h4>
  <div id="popupBody"></div>
</div>
<script>
const DATA = __DATA__;
const META = __META__;

const $ = id => document.getElementById(id);
const tbody = document.querySelector('#data tbody');
const controls = ['search','filterScope','filterAssignment','filterPrincipal','filterRole','filterVia','filterCustom','filterStatus','filterSeverity','filterProtected'].map($);
const [search, fScope, fAssign, fPrincipal, fRole, fVia, fCustom, fStatus, fSeverity, fProtected] = controls;
const toggleAccepted = $('toggleAccepted');
const SEVERITY_RANK = { Critical: 4, High: 3, Medium: 2, Low: 1, Info: 0 };
const INACTIVE = ['Disabled', 'NoValidCredential', 'BlockedByMicrosoft'];

const accepted = new Set();   // reviewed rows, session-only
const selected = new Set();   // ids picked for the removal command, session-only

function esc(s) {
  if (s == null) return '';
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function actionsOf(r) {
  if (Array.isArray(r.RiskyActions)) return r.RiskyActions;
  if (typeof r.RiskyActions === 'string' && r.RiskyActions) return r.RiskyActions.split(';').map(a => a.trim()).filter(Boolean);
  return [];
}
function uniq(list, pred) { return new Set(list.filter(pred).map(r => r.PrincipalId)).size; }

// Header and summary cards from the data itself, so the numbers cannot drift from the rows.
$('subtitle').textContent = `Tenant ${META.tenantName ? META.tenantName + ' (' + (META.tenantId || 'id unknown') + ')' : (META.tenantId || '(unknown)')} · Generated ${META.generated} · ${DATA.length} finding(s)`;
$('version').textContent = META.version ? `v${META.version}` : '';
document.title = META.title;
const cards = [
  ['Total findings', DATA.length, ''],
  ['Critical', DATA.filter(r => r.Severity === 'Critical').length, '#fca5a5'],
  ['High', DATA.filter(r => r.Severity === 'High').length, '#fcd34d'],
  ['Permanent', DATA.filter(r => r.AssignmentType === 'Permanent').length, 'var(--ok)'],
  ['Activated (PIM)', DATA.filter(r => r.AssignmentType === 'Activated').length, '#fdba74'],
  ['Eligible (PIM)', DATA.filter(r => r.AssignmentType === 'Eligible').length, 'var(--warn)'],
  ['Users', uniq(DATA, r => r.PrincipalType === 'User'), ''],
  ['Apps', uniq(DATA, r => r.PrincipalType === 'EnterpriseApp' || r.PrincipalType === 'AppRegistration'), ''],
  ['Managed identities', uniq(DATA, r => r.PrincipalType === 'ManagedIdentity'), ''],
  ['Groups assigned', uniq(DATA, r => r.PrincipalType === 'Group'), ''],
  ['Custom roles', DATA.filter(r => r.IsCustomRole).length, 'var(--err)'],
  ['Inactive principals', DATA.filter(r => INACTIVE.includes(r.ActivityStatus)).length, 'var(--err)'],
  ['Protected', DATA.filter(r => r.Protected).length, '#c4b5fd'],
];
$('summary').innerHTML = cards.map(([label, value, color]) =>
  `<div class="stat"><div class="stat-label">${esc(label)}</div><div class="stat-value"${color ? ` style="color:${color}"` : ''}>${value}</div></div>`).join('');

[...new Set(DATA.map(r => r.RoleName))].sort().forEach(r => {
  const o = document.createElement('option'); o.value = r; o.textContent = r; fRole.appendChild(o);
});

let sortKey = 'RiskScore';
let sortDir = 'desc';
let filtered = DATA.slice();

function applyFilters() {
  const q = search.value.trim().toLowerCase();
  const minRank = fSeverity.value ? SEVERITY_RANK[fSeverity.value] : -1;
  const showAccepted = toggleAccepted.dataset.active === 'true';
  filtered = DATA.filter(r => {
    if (!showAccepted && accepted.has(r.Id)) return false;
    if (fScope.value && r.RoleScope !== fScope.value) return false;
    if (fAssign.value && r.AssignmentType !== fAssign.value) return false;
    if (fPrincipal.value && r.PrincipalType !== fPrincipal.value) return false;
    if (fRole.value && r.RoleName !== fRole.value) return false;
    if (fVia.value === 'direct' && r.ViaGroup) return false;
    if (fVia.value === 'group' && !r.ViaGroup) return false;
    if (fCustom.value === 'custom' && !r.IsCustomRole) return false;
    if (fCustom.value === 'builtin' && r.IsCustomRole) return false;
    if (fStatus.value === 'inactive') { if (!INACTIVE.includes(r.ActivityStatus)) return false; }
    else if (fStatus.value && r.ActivityStatus !== fStatus.value) return false;
    if (minRank >= 0 && (SEVERITY_RANK[r.Severity] ?? 0) < minRank) return false;
    if (fProtected.value === 'removable' && r.Protected) return false;
    if (fProtected.value === 'protected' && !r.Protected) return false;
    if (q) {
      const hay = [r.Id, r.RoleName, r.PrincipalName, r.UPN, r.AppId, r.ScopeName, r.ViaGroup, r.PrincipalId,
                   actionsOf(r).join(' '), r.ActivityReason, r.ScopeDetail, r.ScopeLevel, r.ProtectedReason]
        .filter(Boolean).join(' ').toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });
  applySort();
}

function applySort() {
  filtered.sort((a, b) => {
    let va = a[sortKey], vb = b[sortKey];
    if (sortKey === 'RiskScore') { va = parseFloat(va) || 0; vb = parseFloat(vb) || 0; }
    else if (sortKey === 'Protected') { va = va ? 1 : 0; vb = vb ? 1 : 0; }
    else { va = (va ?? '').toString().toLowerCase(); vb = (vb ?? '').toString().toLowerCase(); }
    if (va < vb) return sortDir === 'asc' ? -1 : 1;
    if (va > vb) return sortDir === 'asc' ? 1 : -1;
    return 0;
  });
  document.querySelectorAll('th[data-key]').forEach(th => {
    th.classList.remove('sorted-asc', 'sorted-desc');
    if (th.dataset.key === sortKey) th.classList.add('sorted-' + sortDir);
  });
  render();
}

function render() {
  const acceptedTotal = accepted.size;
  $('count').textContent = `${filtered.length} of ${DATA.length} findings${acceptedTotal ? ` (${acceptedTotal} accepted)` : ''}`;
  $('empty').style.display = filtered.length ? 'none' : 'block';
  tbody.innerHTML = filtered.map((r, idx) => {
    const upnOrApp = r.UPN || r.AppId || '';
    const customFlag = r.IsCustomRole ? '<span class="custom-flag">CUSTOM</span>' : '';
    const via = r.ViaGroup ? `<div class="via">via group: ${esc(r.ViaGroup)}</div>` : '<span class="mono">direct</span>';
    const actionsHtml = actionsOf(r).map(a => `<span class="action-pill">${esc(a)}</span>`).join('');
    const statusLabel = (r.ActivityStatus || 'Unknown').replace(/([A-Z])/g, ' $1').trim();
    const reason = r.ActivityReason ? `<div class="status-reason">${esc(r.ActivityReason)}</div>` : '';
    const sev = r.Severity || 'Info';
    const scoreHtml = `<span class="score score-${esc(sev)}">${esc(sev.toUpperCase())}</span><div class="score-number">${esc(r.RiskScore)}</div>`;
    const scopeLevel = r.ScopeLevel || 'Other';
    const scopeHtml = `<span class="scope-${esc(scopeLevel)}">${esc(scopeLevel)}</span><div class="scope-detail">${esc(r.ScopeName || r.ScopeDetail || '')}</div>`;
    const protectedHtml = r.Protected
      ? `<span class="badge badge-protected">protected</span><div class="protected-reason">${esc(r.ProtectedReason || '')}</div>`
      : '<span class="mono">-</span>';
    const cleanupHtml = (r.CleanupPrimary || r.CleanupAlt) ? `<button class="small-btn cleanup-btn" data-idx="${idx}">Show</button>` : '<span class="mono">-</span>';
    const isSelected = selected.has(r.Id);
    const isAccepted = accepted.has(r.Id);
    return `
      <tr class="${isAccepted ? 'accepted' : ''}${isSelected ? ' selected' : ''}" data-id="${esc(r.Id)}">
        <td class="select-cell"><input type="checkbox" class="select-cb" data-id="${esc(r.Id)}"${r.Protected ? ' disabled title="Protected: the module will not remove this"' : ''}${isSelected ? ' checked' : ''}></td>
        <td>${scoreHtml}</td>
        <td><span class="badge badge-${esc(r.RoleScope)}">${esc(r.RoleScope)}</span></td>
        <td>${esc(r.RoleName)}${customFlag}</td>
        <td><span class="badge badge-${esc(r.AssignmentType)}">${esc(r.AssignmentType)}</span></td>
        <td><span class="badge badge-${esc(r.PrincipalType)}">${esc(r.PrincipalType)}</span></td>
        <td>
          <div>${esc(r.PrincipalName)}</div>
          ${upnOrApp ? `<div class="mono identity-upn">${esc(upnOrApp)}</div>` : ''}
          <div class="mono identity-id">${esc(r.PrincipalId)} · ${esc(r.Id)}</div>
        </td>
        <td><span class="badge badge-status-${esc(r.ActivityStatus || 'Unknown')}">${esc(statusLabel)}</span>${reason}</td>
        <td>${scopeHtml}</td>
        <td>${via}</td>
        <td>${protectedHtml}</td>
        <td class="actions-cell">${actionsHtml}</td>
        <td>${cleanupHtml}</td>
        <td class="accept-cell"><input type="checkbox" class="accept-cb" data-id="${esc(r.Id)}" title="Mark as accepted / reviewed"${isAccepted ? ' checked' : ''}></td>
      </tr>`;
  }).join('');

  tbody.querySelectorAll('.cleanup-btn').forEach(btn => btn.addEventListener('click', ev => showCleanup(parseInt(btn.dataset.idx, 10), ev)));
  tbody.querySelectorAll('.accept-cb').forEach(cb => cb.addEventListener('change', () => {
    if (cb.checked) accepted.add(cb.dataset.id); else accepted.delete(cb.dataset.id);
    applyFilters();
  }));
  tbody.querySelectorAll('.select-cb').forEach(cb => cb.addEventListener('change', () => {
    if (cb.checked) selected.add(cb.dataset.id); else selected.delete(cb.dataset.id);
    cb.closest('tr').classList.toggle('selected', cb.checked);
    updateSelection();
  }));
  updateSelection();
}

function updateSelection() {
  $('selectionCount').textContent = `${selected.size} selected`;
  $('copyRemoval').disabled = selected.size === 0;
}

function removalCommand(ids) {
  const list = ids.map(i => `'${i}'`).join(', ');
  return [
    `# RiskyRolesAnalyzer: ${ids.length} assignment(s) selected in the report generated ${META.generated}`,
    `# $findings is the output of Get-RiskyRoleAssignment. Run it again if the variable is gone.`,
    `$findings | Where-Object Id -in @(${list}) | Remove-RiskyRoleAssignment -WhatIf`,
    `# Drop -WhatIf to remove. Each assignment is confirmed and written to a backup file before the call.`
  ].join('\n');
}

function openPopup(title, html, ev) {
  const popup = $('popup');
  $('popupTitle').textContent = title;
  $('popupBody').innerHTML = html;
  $('popupBody').querySelectorAll('[data-copy-from]').forEach(btn => btn.addEventListener('click', e => {
    e.stopPropagation();
    const source = $(btn.dataset.copyFrom);
    if (!source) return;
    navigator.clipboard.writeText(source.textContent).then(() => {
      btn.textContent = 'Copied'; btn.classList.add('copied');
      setTimeout(() => { btn.textContent = 'Copy'; btn.classList.remove('copied'); }, 1500);
    }).catch(() => { btn.textContent = 'Select the text and copy'; setTimeout(() => { btn.textContent = 'Copy'; }, 2500); });
  }));
  const x = ev ? Math.min(ev.clientX, window.innerWidth - 740) : 40;
  const y = ev ? Math.min(ev.clientY, window.innerHeight - 320) : 120;
  popup.style.left = Math.max(10, x) + 'px';
  popup.style.top = Math.max(10, y) + 'px';
  popup.style.display = 'block';
}

function showCleanup(idx, ev) {
  const r = filtered[idx];
  if (!r) return;
  let html = '';
  if (r.Protected) html += `<div class="note">Protected: ${esc(r.ProtectedReason)}. The module reports this and does not remove it; the native command below is for you to judge.</div>`;
  if (r.RoleScope === 'Entra') html += `<div class="prereq-box"><div class="prereq-title">Prerequisite</div>Graph session with <code>RoleManagement.ReadWrite.Directory</code>: <code>Connect-RiskyRolesAnalyzer -RequestWriteScopes</code></div>`;
  if (r.ViaGroup) html += `<div class="note"><strong>${esc(r.PrincipalName)}</strong> inherits this role through group <strong>${esc(r.ViaGroup)}</strong>. Choose the right scope:</div>`;
  if (r.CleanupPrimary) {
    html += `<div class="note">${r.ViaGroup ? 'Option A, remove only this principal from the group:' : 'Native command:'}</div>`;
    html += `<pre id="cleanupPrimary">${esc(r.CleanupPrimary)}</pre><button class="small-btn" data-copy-from="cleanupPrimary">Copy</button>`;
  }
  if (r.CleanupAlt) {
    html += `<div class="note" style="margin-top:12px">Option B, remove the role from the entire group (affects all members):</div>`;
    html += `<pre id="cleanupAlt">${esc(r.CleanupAlt)}</pre><button class="small-btn" data-copy-from="cleanupAlt">Copy</button>`;
  }
  if (!r.Protected) {
    html += `<div class="note" style="margin-top:12px">Or through the module, with prompt and backup:</div>`;
    html += `<pre id="cleanupModule">${esc(removalCommand([r.Id]))}</pre><button class="small-btn" data-copy-from="cleanupModule">Copy</button>`;
  }
  openPopup('Cleanup', html, ev);
}

$('copyRemoval').addEventListener('click', ev => {
  const ids = DATA.filter(r => selected.has(r.Id)).map(r => r.Id);
  if (!ids.length) return;
  const html = `<div class="note">${ids.length} assignment(s). Paste into the PowerShell session that ran <code>Get-RiskyRoleAssignment</code>.</div>` +
               `<pre id="removalText">${esc(removalCommand(ids))}</pre><button class="small-btn" data-copy-from="removalText">Copy</button>`;
  openPopup('Removal command', html, ev);
});
$('selectVisible').addEventListener('click', () => { filtered.filter(r => !r.Protected).forEach(r => selected.add(r.Id)); render(); });
$('clearSelection').addEventListener('click', () => { selected.clear(); render(); });
$('popupClose').addEventListener('click', () => { $('popup').style.display = 'none'; });
document.addEventListener('click', ev => {
  const popup = $('popup');
  if (popup.style.display === 'block' && !popup.contains(ev.target) && !ev.target.classList.contains('cleanup-btn') && ev.target.id !== 'copyRemoval') popup.style.display = 'none';
});
document.querySelectorAll('th[data-key]').forEach(th => th.addEventListener('click', () => {
  const k = th.dataset.key;
  if (sortKey === k) sortDir = sortDir === 'asc' ? 'desc' : 'asc'; else { sortKey = k; sortDir = 'asc'; }
  applySort();
}));
controls.forEach(el => el.addEventListener('input', applyFilters));
toggleAccepted.addEventListener('click', () => {
  const isActive = toggleAccepted.dataset.active === 'true';
  toggleAccepted.dataset.active = (!isActive).toString();
  toggleAccepted.textContent = isActive ? 'Show accepted' : 'Hide accepted';
  applyFilters();
});
$('exportCsv').addEventListener('click', () => {
  const cols = ['Id','Severity','RiskScore','RoleScope','RoleName','IsCustomRole','RiskyActions','AssignmentType','AssignmentId',
                'PrincipalType','PrincipalName','PrincipalId','UPN','AppId','AccountEnabled','ActivityStatus','ActivityReason',
                'ScopeLevel','ScopeDetail','ScopeName','Scope','ViaGroup','ViaGroupId','Protected','ProtectedReason','CleanupPrimary','CleanupAlt'];
  const escCsv = v => v == null ? '' : `"${String(Array.isArray(v) ? v.join('; ') : v).replace(/"/g, '""')}"`;
  const lines = [cols.join(',')];
  filtered.forEach(r => lines.push(cols.map(c => escCsv(r[c])).join(',')));
  const blob = new Blob([lines.join('\n')], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = 'risky-role-assignments.csv'; a.click();
  URL.revokeObjectURL(url);
});

applyFilters();
</script>
</body>
</html>
'@

# ---- Rules and collectors (src/RiskyRolesAnalyzer/Private) --------------------------------------

function ConvertTo-PowerShellLiteral {
    <#
    .SYNOPSIS
    Make a value safe to paste inside a single-quoted PowerShell string.
    .DESCRIPTION
    The cleanup commands in the report are text a person copies into a shell, and role and group
    names come from the tenant being audited. A name holding an apostrophe would end the quoted
    string early: 'Simon's Admin Role' is a syntax error, and a name crafted as
    "x'; <command> #" would turn the pasted line into something else. Doubling the apostrophe is
    how PowerShell escapes it inside a single-quoted string. Line breaks are collapsed as well,
    so a name can neither end a comment line nor start a statement of its own.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$Value
    )

    if ([string]::IsNullOrEmpty($Value)) { return '' }
    return ($Value -replace '[\r\n\t]+', ' ').Replace("'", "''")
}

function ConvertTo-RiskyRoleReportHtml {
    <#
    .SYNOPSIS
    Render findings into the self-contained HTML report.
    .DESCRIPTION
    Pure: findings in, one HTML string out. The page lives in Resources/report.html with three
    placeholders (__TITLE__, __DATA__, __META__); the findings go in as a JSON array without the
    raw Source objects. Counts, filters and the removal command are computed in the page from that
    array, so the numbers on the cards cannot drift from the rows. Nothing in the page calls out.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter()]
        [AllowNull()]
        [AllowEmptyCollection()]
        [object[]]$InputObject,

        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$TenantId,

        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$TenantName,

        [Parameter()]
        [string]$Title = 'Privileged Role Audit',

        [Parameter()]
        [datetime]$GeneratedAt = (Get-Date)
    )

    $template = Get-RiskyRoleReportTemplate

    $rows = [System.Collections.Generic.List[object]]::new()
    foreach ($item in @($InputObject)) {
        if ($null -eq $item) { continue }
        $rows.Add(($item | Select-Object -Property * -ExcludeProperty Source))
    }
    $data = if ($rows.Count) { ConvertTo-Json -InputObject $rows.ToArray() -Depth 6 -Compress } else { '[]' }
    $meta = ConvertTo-Json -InputObject @{
        title     = $Title
        tenantId  = $TenantId
        tenantName = $TenantName
        generated = $GeneratedAt.ToString('yyyy-MM-dd HH:mm:ss')
        version   = $script:ModuleVersion
        count     = $rows.Count
    } -Compress

    # A closing tag inside a JSON string would end the script block; escape the slash.
    $data = $data.Replace('</', '<\/')
    $meta = $meta.Replace('</', '<\/')
    $safeTitle = [System.Net.WebUtility]::HtmlEncode($Title)

    return $template.Replace('__TITLE__', $safeTitle).Replace('__DATA__', $data).Replace('__META__', $meta)
}

function ConvertTo-RiskyRoleSeverity {
    <#
    .SYNOPSIS
    Map a 0.0 to 10.0 score to the severity label used everywhere else.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)]
        [double]$Score
    )

    foreach ($band in $script:Catalog.Scoring.Severity) {
        if ($Score -ge $band.Minimum) { return [string]$band.Name }
    }
    return 'Info'
}

function Get-ApplicationInventory {
    <#
    .SYNOPSIS
    Load every app registration once, with its credential state and the portal's "deactivated" flag.
    .DESCRIPTION
    Two passes: v1.0 for credentials (start and end dates decide whether any is usable now) and
    /beta for isDisabled, the App Registration "Deactivated" toggle, which v1.0 does not expose.
    The beta pass is best effort; without it deactivated app registrations look active.
    Returns a hashtable keyed by appId.
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter()]
        [datetime]$Now = (Get-Date)
    )

    $inventory = @{}

    $apps = Get-GraphCollection -Uri 'https://graph.microsoft.com/v1.0/applications?$select=id,appId,displayName,passwordCredentials,keyCredentials&$top=999'
    foreach ($app in $apps) {
        $appId = [string](Get-PropertyOrDefault -InputObject $app -Name 'appId' -Default '')
        if (-not $appId) { continue }
        $summary = Get-CredentialSummary -Application $app -Now $Now
        $inventory[$appId] = [pscustomobject]@{
            Id                 = Get-PropertyOrDefault -InputObject $app -Name 'id' -Default $null
            AppId              = $appId
            DisplayName        = Get-PropertyOrDefault -InputObject $app -Name 'displayName' -Default $null
            CredentialCount    = $summary.CredentialCount
            ExpiredCount       = $summary.ExpiredCount
            HasValidCredential = $summary.HasValidCredential
            IsDisabled         = $false
        }
    }

    try {
        $flags = Get-GraphCollection -Uri 'https://graph.microsoft.com/beta/applications?$select=appId,isDisabled&$top=999'
        foreach ($flag in $flags) {
            $appId = [string](Get-PropertyOrDefault -InputObject $flag -Name 'appId' -Default '')
            if ($appId -and $inventory.ContainsKey($appId) -and (Get-PropertyOrDefault -InputObject $flag -Name 'isDisabled' -Default $false) -eq $true) {
                $inventory[$appId].IsDisabled = $true
            }
        }
    }
    catch {
        Write-Warning "Could not read isDisabled from the Graph beta endpoint; deactivated app registrations will show as active. $($_.Exception.Message)"
    }

    Write-Verbose "$($inventory.Count) app registrations loaded"
    return $inventory
}

function Get-AzureRoleFinding {
    <#
    .SYNOPSIS
    Privileged Azure RBAC assignments across the enabled subscriptions of one tenant.
    .DESCRIPTION
    Per subscription: custom role definitions are checked for risky actions, then every
    assignment visible at subscription scope (including the ones inherited from management
    groups and the root) is kept when its role is a privileged built-in or a risky custom role.
    Assignments inherited from above appear in every subscription; each is reported once.
    Group principals are expanded so every member is listed with the group it inherits through.
    The Az context is switched per subscription and restored afterwards.
    #>
    [CmdletBinding()]
    [OutputType('RiskyRolesAnalyzer.RiskyRoleAssignment')]
    param(
        [Parameter(Mandatory)]
        [hashtable]$Audit,

        [Parameter(Mandatory)]
        [string]$TenantId,

        [Parameter()]
        [AllowNull()]
        [string[]]$SubscriptionId
    )

    $subscriptions = @(Get-AzSubscription -TenantId $TenantId -ErrorAction Stop | Where-Object { $_.State -eq 'Enabled' })
    if ($SubscriptionId) {
        $wanted = @($SubscriptionId | ForEach-Object { $_.ToLowerInvariant() })
        $subscriptions = @($subscriptions | Where-Object { $_.Id.ToLowerInvariant() -in $wanted })
        foreach ($id in $wanted) {
            if ($id -notin @($subscriptions | ForEach-Object { $_.Id.ToLowerInvariant() })) { Write-Warning "Subscription $id is not enabled in tenant $TenantId or not visible to this account." }
        }
    }
    Write-Verbose "$($subscriptions.Count) enabled subscription(s) in tenant $TenantId"
    if ($subscriptions.Count -eq 0) {
        Write-Warning "No enabled subscriptions found in tenant $TenantId. Check Get-AzSubscription and Connect-AzAccount -TenantId $TenantId."
        return
    }

    $roleCache = @{}   # role definition id -> @{ Name; Risky }
    $seenAssignments = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $originalContext = Get-AzContext -ErrorAction SilentlyContinue

    try {
        $index = 0
        foreach ($subscription in $subscriptions) {
            $index++
            Write-Progress -Activity 'Azure RBAC' -Status "$($subscription.Name) ($index/$($subscriptions.Count))" -PercentComplete (100 * ($index - 1) / $subscriptions.Count)
            Write-Verbose "[$index/$($subscriptions.Count)] $($subscription.Name)"
            $null = Set-AzContext -SubscriptionId $subscription.Id -TenantId $TenantId -ErrorAction Stop

            try {
                foreach ($definition in @(Get-AzRoleDefinition -Custom -ErrorAction Stop)) {
                    if ($roleCache.ContainsKey($definition.Id)) { continue }
                    # Az.Resources 10 nests the actions in Permissions[]; older versions flatten them. Rate the union.
                    $risky = [System.Collections.Generic.List[string]]::new()
                    foreach ($permission in @(Get-RoleDefinitionPermission -Definition $definition)) {
                        foreach ($action in @(Get-RiskyRoleAction -Action $permission.Actions -NotAction $permission.NotActions -DataAction $permission.DataActions -NotDataAction $permission.NotDataActions -RiskyAction $Audit.RiskyAzureActions)) {
                            if ($action -notin $risky) { $risky.Add($action) }
                        }
                    }
                    $roleCache[$definition.Id] = @{ Name = $definition.Name; Risky = $risky.ToArray() }
                }
            }
            catch { Write-Warning "Could not list role definitions in $($subscription.Name): $($_.Exception.Message)" }

            try {
                $assignments = @(Get-AzRoleAssignment -Scope "/subscriptions/$($subscription.Id)" -ErrorAction Stop)
            }
            catch {
                Write-Warning "Could not list role assignments in $($subscription.Name): $($_.Exception.Message)"
                continue
            }

            foreach ($assignment in $assignments) {
                $isCustom = $roleCache.ContainsKey($assignment.RoleDefinitionId)
                $risky = @()
                if ($isCustom) { $risky = @($roleCache[$assignment.RoleDefinitionId].Risky) }
                $privileged = ($assignment.RoleDefinitionName -in $Audit.PrivilegedAzureRoles) -or ($isCustom -and $risky.Count -gt 0)
                if (-not $privileged) { continue }
                if ($assignment.RoleAssignmentId -and -not $seenAssignments.Add($assignment.RoleAssignmentId)) { continue }

                $scopeName = if ($assignment.Scope -like "/subscriptions/$($subscription.Id)*") { $subscription.Name } else { (Resolve-RoleScope -Scope $assignment.Scope -RoleScope Azure).Detail }
                $common = @{
                    RoleScope        = 'Azure'
                    RoleName         = $assignment.RoleDefinitionName
                    RoleDefinitionId = $assignment.RoleDefinitionId
                    Scope            = $assignment.Scope
                    ScopeName        = $scopeName
                    AssignmentType   = 'Permanent'
                    AssignmentId     = $assignment.RoleAssignmentId
                    IsCustomRole     = $isCustom
                    RiskyAction      = $risky
                    BreakGlassAccount = $Audit.BreakGlassAccount
                    CurrentAccount   = $Audit.CurrentAccount
                    Source           = $assignment
                }

                $principal = Resolve-DirectoryPrincipal -ObjectId $assignment.ObjectId -Audit $Audit
                Resolve-RiskyRoleAssignmentFinding @common -Principal $principal
                if ($principal.Type -eq 'Group') {
                    foreach ($member in @(Get-GroupMemberRecursive -GroupId $principal.ObjectId -Audit $Audit)) {
                        Resolve-RiskyRoleAssignmentFinding @common -Principal $member -ViaGroup $principal.DisplayName -ViaGroupId $principal.ObjectId
                    }
                }
            }
        }
    }
    finally {
        Write-Progress -Activity 'Azure RBAC' -Completed
        $originalSubscription = Get-PropertyOrDefault -InputObject (Get-PropertyOrDefault -InputObject $originalContext -Name 'Subscription' -Default $null) -Name 'Id' -Default $null
        if ($originalSubscription) { $null = Set-AzContext -SubscriptionId $originalSubscription -TenantId $TenantId -ErrorAction SilentlyContinue }
    }
}

function Get-CredentialSummary {
    <#
    .SYNOPSIS
    Count an application's secrets and certificates and say whether any of them is usable now.
    .DESCRIPTION
    Pure rule over the passwordCredentials and keyCredentials arrays of a Graph application
    object. A credential is valid when its start date is not in the future and its end date is
    not in the past. -Now exists so tests can pin the clock.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]
        $Application,

        [Parameter()]
        [datetime]$Now = (Get-Date)
    )

    $all = @()
    foreach ($name in 'passwordCredentials', 'keyCredentials') {
        $list = Get-PropertyOrDefault -InputObject $Application -Name $name -Default @()
        if ($list) { $all += @($list) }
    }

    $count = 0
    $expired = 0
    $hasValid = $false
    foreach ($credential in $all) {
        if (-not $credential) { continue }
        $count++
        $start = Get-PropertyOrDefault -InputObject $credential -Name 'startDateTime' -Default $null
        $end = Get-PropertyOrDefault -InputObject $credential -Name 'endDateTime' -Default $null
        $valid = $true
        if ($start) { try { if ([datetime]$start -gt $Now) { $valid = $false } } catch { Write-Verbose "Unreadable startDateTime '$start'" } }
        if ($end) { try { if ([datetime]$end -lt $Now) { $valid = $false; $expired++ } } catch { Write-Verbose "Unreadable endDateTime '$end'" } }
        if ($valid) { $hasValid = $true }
    }

    [pscustomobject]@{
        CredentialCount    = $count
        ExpiredCount       = $expired
        HasValidCredential = $hasValid
    }
}

function Get-EntraRoleFinding {
    <#
    .SYNOPSIS
    Privileged Entra ID directory role assignments, permanent and PIM eligible.
    .DESCRIPTION
    Reads every role definition with its permissions so custom directory roles that grant risky
    actions count as privileged next to the built-in list. Permanent assignments come from
    roleAssignments; eligible ones from roleEligibilitySchedules, which needs Entra ID P2 and is
    skipped with a warning when the tenant or the scopes do not allow it. A permanent-looking
    assignment that roleAssignmentSchedules reports as Activated is a PIM activation and is
    typed Activated (and protected) instead. Group principals are expanded like in Azure.
    #>
    [CmdletBinding()]
    [OutputType('RiskyRolesAnalyzer.RiskyRoleAssignment')]
    param(
        [Parameter(Mandatory)]
        [hashtable]$Audit,

        [Parameter()]
        [switch]$SkipPim
    )

    $definitions = Get-GraphCollection -Uri 'https://graph.microsoft.com/v1.0/roleManagement/directory/roleDefinitions'
    $privileged = @{}   # role definition id -> @{ Name; IsCustom; Risky }
    foreach ($definition in $definitions) {
        $id = [string](Get-PropertyOrDefault -InputObject $definition -Name 'id' -Default '')
        $name = [string](Get-PropertyOrDefault -InputObject $definition -Name 'displayName' -Default '')
        $isBuiltIn = Get-PropertyOrDefault -InputObject $definition -Name 'isBuiltIn' -Default $true
        if ($null -eq $isBuiltIn) { $isBuiltIn = $true }
        if (-not $id) { continue }

        if ($isBuiltIn) {
            if ($name -in $Audit.PrivilegedEntraRoles) { $privileged[$id] = @{ Name = $name; IsCustom = $false; Risky = @() } }
            continue
        }

        $allowed = [System.Collections.Generic.List[string]]::new()
        foreach ($permission in @(Get-PropertyOrDefault -InputObject $definition -Name 'rolePermissions' -Default @())) {
            foreach ($action in @(Get-PropertyOrDefault -InputObject $permission -Name 'allowedResourceActions' -Default @())) { if ($action) { $allowed.Add([string]$action) } }
        }
        $risky = @(Get-RiskyRoleAction -Action $allowed.ToArray() -RiskyAction $Audit.RiskyEntraActions)
        if ($risky.Count -gt 0) { $privileged[$id] = @{ Name = $name; IsCustom = $true; Risky = $risky } }
    }
    Write-Verbose "$($privileged.Count) privileged Entra role definitions (built-in and custom)"

    # PIM activations show up in roleAssignments like permanent ones; the schedules tell them apart.
    $activated = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    if (-not $SkipPim) {
        try {
            foreach ($schedule in @(Get-GraphCollection -Uri 'https://graph.microsoft.com/v1.0/roleManagement/directory/roleAssignmentSchedules')) {
                if ((Get-PropertyOrDefault -InputObject $schedule -Name 'assignmentType' -Default '') -ne 'Activated') { continue }
                $key = @((Get-PropertyOrDefault -InputObject $schedule -Name 'principalId' -Default ''), (Get-PropertyOrDefault -InputObject $schedule -Name 'roleDefinitionId' -Default ''), (Get-PropertyOrDefault -InputObject $schedule -Name 'directoryScopeId' -Default '/')) -join '|'
                $null = $activated.Add($key)
            }
            Write-Verbose "$($activated.Count) PIM activation(s) in progress"
        }
        catch {
            Write-Verbose "Could not read roleAssignmentSchedules; PIM activations will show as Permanent. $($_.Exception.Message)"
        }
    }

    $sources = @(@{ Uri = 'https://graph.microsoft.com/v1.0/roleManagement/directory/roleAssignments'; Type = 'Permanent' })
    if (-not $SkipPim) { $sources += @{ Uri = 'https://graph.microsoft.com/v1.0/roleManagement/directory/roleEligibilitySchedules'; Type = 'Eligible' } }

    foreach ($source in $sources) {
        Write-Progress -Activity 'Entra ID roles' -Status $source.Type
        try {
            $assignments = @(Get-GraphCollection -Uri $source.Uri)
        }
        catch {
            if ($source.Type -eq 'Eligible') { Write-Warning "PIM eligible assignments skipped: $($_.Exception.Message). Entra ID P2 and RoleManagement.Read.Directory are required; use -SkipPim to silence this." }
            else { throw }
            continue
        }

        foreach ($assignment in $assignments) {
            $roleId = [string](Get-PropertyOrDefault -InputObject $assignment -Name 'roleDefinitionId' -Default '')
            if (-not $privileged.ContainsKey($roleId)) { continue }
            $principalId = [string](Get-PropertyOrDefault -InputObject $assignment -Name 'principalId' -Default '')
            if (-not $principalId) { continue }
            $role = $privileged[$roleId]
            $directoryScope = [string](Get-PropertyOrDefault -InputObject $assignment -Name 'directoryScopeId' -Default '/')
            $assignmentType = $source.Type
            if ($assignmentType -eq 'Permanent' -and $activated.Contains("$principalId|$roleId|$directoryScope")) { $assignmentType = 'Activated' }

            $common = @{
                RoleScope        = 'Entra'
                RoleName         = $role.Name
                RoleDefinitionId = $roleId
                Scope            = $directoryScope
                ScopeName        = (Resolve-RoleScope -Scope $directoryScope -RoleScope Entra).Detail
                AssignmentType   = $assignmentType
                AssignmentId     = [string](Get-PropertyOrDefault -InputObject $assignment -Name 'id' -Default '')
                IsCustomRole     = $role.IsCustom
                RiskyAction      = $role.Risky
                BreakGlassAccount = $Audit.BreakGlassAccount
                CurrentAccount   = $Audit.CurrentAccount
                Source           = $assignment
            }

            $principal = Resolve-DirectoryPrincipal -ObjectId $principalId -Audit $Audit
            Resolve-RiskyRoleAssignmentFinding @common -Principal $principal
            if ($principal.Type -eq 'Group') {
                foreach ($member in @(Get-GroupMemberRecursive -GroupId $principal.ObjectId -Audit $Audit)) {
                    Resolve-RiskyRoleAssignmentFinding @common -Principal $member -ViaGroup $principal.DisplayName -ViaGroupId $principal.ObjectId
                }
            }
        }
    }
    Write-Progress -Activity 'Entra ID roles' -Completed
}

function Get-GraphCollection {
    <#
    .SYNOPSIS
    GET a Graph collection and follow @odata.nextLink until the end.
    .DESCRIPTION
    The one place the module pages through Graph. Returns the items of every page's "value"
    array. Errors propagate; callers decide whether a failed endpoint is fatal (role
    definitions) or a warning (PIM on a tenant without P2).
    #>
    [CmdletBinding()]
    [OutputType([object[]])]
    param(
        [Parameter(Mandatory)]
        [string]$Uri
    )

    $items = [System.Collections.Generic.List[object]]::new()
    $next = $Uri
    while ($next) {
        $response = Invoke-MgGraphRequest -Method GET -Uri $next -ErrorAction Stop
        foreach ($item in @(Get-PropertyOrDefault -InputObject $response -Name 'value' -Default @())) {
            if ($null -ne $item) { $items.Add($item) }
        }
        $next = Get-PropertyOrDefault -InputObject $response -Name '@odata.nextLink' -Default $null
    }
    return $items.ToArray()
}

function Get-GroupMemberRecursive {
    <#
    .SYNOPSIS
    Every non-group member of a group, through any depth of nesting.
    .DESCRIPTION
    Walks group members recursively, resolves each leaf with Resolve-DirectoryPrincipal and
    caches the flat list per group in $Audit.Cache.Groups. A group that contains itself through
    a cycle is visited once.
    #>
    [CmdletBinding()]
    [OutputType([object[]])]
    param(
        [Parameter(Mandatory)]
        [string]$GroupId,

        [Parameter(Mandatory)]
        [hashtable]$Audit,

        [Parameter()]
        [System.Collections.Generic.HashSet[string]]$Seen
    )

    if (-not $Seen) { $Seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase) }
    if ($Audit.Cache.Groups.ContainsKey($GroupId)) { return $Audit.Cache.Groups[$GroupId] }
    if (-not $Seen.Add($GroupId)) { return @() }

    $leaves = [System.Collections.Generic.List[object]]::new()
    try {
        $members = Get-GraphCollection -Uri "https://graph.microsoft.com/v1.0/groups/$GroupId/members?`$select=id&`$top=999"
        foreach ($member in $members) {
            $memberId = [string](Get-PropertyOrDefault -InputObject $member -Name 'id' -Default '')
            if (-not $memberId) { continue }
            $type = [string](Get-PropertyOrDefault -InputObject $member -Name '@odata.type' -Default '')
            if ($type -like '*.group') {
                foreach ($nested in @(Get-GroupMemberRecursive -GroupId $memberId -Audit $Audit -Seen $Seen)) { $leaves.Add($nested) }
            }
            else {
                $resolved = Resolve-DirectoryPrincipal -ObjectId $memberId -Audit $Audit
                if ($resolved) { $leaves.Add($resolved) }
            }
        }
    }
    catch {
        Write-Warning "Could not list members of group $GroupId : $($_.Exception.Message)"
    }

    $Audit.Cache.Groups[$GroupId] = $leaves.ToArray()
    return $Audit.Cache.Groups[$GroupId]
}

function Get-PropertyOrDefault {
    <#
    .SYNOPSIS
    Read a property from a hashtable or object without tripping strict mode.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowNull()]
        $InputObject,

        [Parameter(Mandatory)]
        [string]$Name,

        [Parameter()]
        $Default = $null
    )

    if ($null -eq $InputObject) { return $Default }
    if ($InputObject -is [System.Collections.IDictionary]) {
        if ($InputObject.Contains($Name)) { return $InputObject[$Name] }
        return $Default
    }
    $property = $InputObject.PSObject.Properties[$Name]
    if ($property) { return $property.Value }
    return $Default
}

function Get-RiskyRoleAction {
    <#
    .SYNOPSIS
    The risky actions a role definition really grants, after NotActions are applied.
    .DESCRIPTION
    Pure rule: takes the four permission lists of an Azure RBAC role (Entra roles only have
    allowed actions) and the list of actions considered risky, returns the risky actions that are
    granted by Actions or DataActions and not taken away by NotActions or NotDataActions.
    #>
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [Parameter()]
        [AllowNull()]
        [string[]]$Action,

        [Parameter()]
        [AllowNull()]
        [string[]]$NotAction,

        [Parameter()]
        [AllowNull()]
        [string[]]$DataAction,

        [Parameter()]
        [AllowNull()]
        [string[]]$NotDataAction,

        [Parameter(Mandatory)]
        [string[]]$RiskyAction
    )

    $granting = @(@($Action) + @($DataAction) | Where-Object { $_ })
    $blocking = @(@($NotAction) + @($NotDataAction) | Where-Object { $_ })

    $hits = [System.Collections.Generic.List[string]]::new()
    foreach ($risky in $RiskyAction) {
        $granted = $false
        foreach ($pattern in $granting) {
            if (Test-RiskyRoleActionMatch -Pattern $pattern -Action $risky) { $granted = $true; break }
        }
        if (-not $granted) { continue }

        $blocked = $false
        foreach ($pattern in $blocking) {
            if (Test-RiskyRoleActionMatch -Pattern $pattern -Action $risky) { $blocked = $true; break }
        }
        if (-not $blocked) { $hits.Add($risky) }
    }

    return [string[]]$hits
}

function Get-RiskyRoleCleanupCommand {
    <#
    .SYNOPSIS
    Native Az or Graph commands that would remove one finding, for people who want to see the call.
    .DESCRIPTION
    Pure rule. Returns Primary and Alt. Findings inherited through a group get the membership
    removal as Primary and the group's own assignment as Alt; PIM eligibility is a portal task.
    Remove-RiskyRoleAssignment does not run these strings, it makes the equivalent call itself.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]
        [ValidateSet('Azure', 'Entra')]
        [string]$RoleScope,

        [Parameter(Mandatory)]
        [string]$RoleName,

        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$Scope,

        [Parameter(Mandatory)]
        [string]$PrincipalId,

        [Parameter(Mandatory)]
        [ValidateSet('Permanent', 'Eligible', 'Activated')]
        [string]$AssignmentType,

        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$AssignmentId,

        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$ViaGroupId
    )

    # Everything that lands inside a quoted string in a command a person may paste.
    $roleLiteral = ConvertTo-PowerShellLiteral -Value $RoleName
    $scopeLiteral = ConvertTo-PowerShellLiteral -Value $Scope
    $principalLiteral = ConvertTo-PowerShellLiteral -Value $PrincipalId
    $groupLiteral = ConvertTo-PowerShellLiteral -Value $ViaGroupId
    $assignmentLiteral = ConvertTo-PowerShellLiteral -Value $AssignmentId

    $primary = $null
    $alt = $null

    if ($ViaGroupId) {
        $primary = "Remove-AzADGroupMember -GroupObjectId '$groupLiteral' -MemberObjectId '$principalLiteral'"
        $alt = if ($RoleScope -eq 'Azure') {
            "Remove-AzRoleAssignment -ObjectId '$groupLiteral' -RoleDefinitionName '$roleLiteral' -Scope '$scopeLiteral'  # removes the role for the ENTIRE group"
        }
        elseif ($AssignmentId) {
            "Invoke-MgGraphRequest -Method DELETE -Uri 'https://graph.microsoft.com/v1.0/roleManagement/directory/roleAssignments/$assignmentLiteral'  # removes the role for the ENTIRE group"
        }
        else {
            "# Remove the group's assignment in the Entra portal: Roles and administrators > $roleLiteral"
        }
    }
    elseif ($RoleScope -eq 'Azure') {
        $primary = "Remove-AzRoleAssignment -ObjectId '$principalLiteral' -RoleDefinitionName '$roleLiteral' -Scope '$scopeLiteral'"
    }
    elseif ($AssignmentType -eq 'Eligible') {
        $primary = "# Remove the PIM eligibility of '$principalLiteral' for '$roleLiteral' in the Entra portal: PIM > Entra roles > Eligible assignments"
    }
    elseif ($AssignmentType -eq 'Activated') {
        $primary = "# '$principalLiteral' has activated '$roleLiteral' through PIM. Deactivate it or remove the eligibility in PIM; deleting the assignment only ends this activation."
    }
    elseif ($AssignmentId) {
        $primary = "Invoke-MgGraphRequest -Method DELETE -Uri 'https://graph.microsoft.com/v1.0/roleManagement/directory/roleAssignments/$assignmentLiteral'"
    }
    else {
        $primary = "# Remove the assignment of '$principalLiteral' for '$roleLiteral' in the Entra portal: Roles and administrators > $roleLiteral"
    }

    [pscustomobject]@{ Primary = $primary; Alt = $alt }
}

function Get-RiskyRoleFindingId {
    <#
    .SYNOPSIS
    A short, stable identifier for one finding.
    .DESCRIPTION
    The first twelve hex characters of a SHA-256 over the finding's key facts, so the same
    assignment gets the same Id on every run and reports can refer to it. The Id says nothing
    about the tenant on its own.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)]
        [string]$RoleScope,

        [Parameter(Mandatory)]
        [string]$RoleName,

        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$Scope,

        [Parameter(Mandatory)]
        [string]$PrincipalId,

        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$ViaGroupId,

        [Parameter(Mandatory)]
        [string]$AssignmentType
    )

    $key = (@($RoleScope, $RoleName, $Scope, $PrincipalId, $ViaGroupId, $AssignmentType) -join '|').ToLowerInvariant()
    $hash = [System.Security.Cryptography.SHA256]::HashData([System.Text.Encoding]::UTF8.GetBytes($key))
    return [System.Convert]::ToHexString($hash).Substring(0, 12).ToLowerInvariant()
}

function Get-RiskyRoleGridCommand {
    <#
    .SYNOPSIS
    The grid view available on this host, or nothing.
    .DESCRIPTION
    Out-ConsoleGridView (Microsoft.PowerShell.ConsoleGuiTools, any platform) first, then
    Out-GridView (Windows). Both take -Title and -OutputMode Multiple. Separate so tests can
    substitute a grid without a terminal.
    #>
    [CmdletBinding()]
    [OutputType([System.Management.Automation.CommandInfo])]
    param()

    foreach ($name in 'Out-ConsoleGridView', 'Out-GridView') {
        $command = Get-Command -Name $name -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($command) { return $command }
    }
    return $null
}

function Get-RiskyRoleScore {
    <#
    .SYNOPSIS
    Score one finding from 0.0 to 10.0.
    .DESCRIPTION
    Pure rule driven by the Scoring section of RiskyRoleCatalog.psd1: a base score per role
    (critical, high, medium, custom-with-risky-actions or default), multiplied by scope breadth,
    then modified for PIM eligibility, application principals and principals that cannot sign in.
    The score expresses live exploitability; a disabled Global Administrator scores lower than an
    enabled one even though both should go.
    #>
    [CmdletBinding()]
    [OutputType([double])]
    param(
        [Parameter(Mandatory)]
        [string]$RoleName,

        [Parameter(Mandatory)]
        [string]$ScopeLevel,

        [Parameter(Mandatory)]
        [string]$PrincipalType,

        [Parameter(Mandatory)]
        [ValidateSet('Permanent', 'Eligible', 'Activated')]
        [string]$AssignmentType,

        [Parameter()]
        [bool]$IsCustomRole = $false,

        [Parameter()]
        [AllowNull()]
        [string[]]$RiskyAction,

        [Parameter()]
        [string]$ActivityStatus = 'Active'
    )

    $rules = $script:Catalog.Scoring
    $risky = @($RiskyAction | Where-Object { $_ })

    $base = $rules.DefaultBase
    if ($RoleName -in $rules.CriticalRoles) { $base = $rules.CriticalRoleBase }
    elseif ($RoleName -in $rules.HighRoles) { $base = $rules.HighRoleBase }
    elseif ($RoleName -in $rules.MediumRoles) { $base = $rules.MediumRoleBase }

    if ($IsCustomRole) {
        $base = $rules.CustomRoleBase
        foreach ($action in $risky) {
            if ($action -in $rules.CriticalActions) { $base = [Math]::Max($base, $rules.CriticalRoleBase) }
        }
        if ($risky.Count -ge 3) { $base += $rules.StackedActionBonus }
    }

    $multiplier = if ($rules.ScopeMultiplier.ContainsKey($ScopeLevel)) { $rules.ScopeMultiplier[$ScopeLevel] } else { $rules.ScopeMultiplier['Other'] }
    $score = $base * $multiplier

    if ($AssignmentType -eq 'Eligible') { $score += $rules.EligibleModifier }
    if ($PrincipalType -in 'EnterpriseApp', 'AppRegistration', 'ManagedIdentity') { $score += $rules.ApplicationModifier }
    if ($rules.ActivityModifier.ContainsKey($ActivityStatus)) { $score += $rules.ActivityModifier[$ActivityStatus] }

    # Away from zero, so 7.65 reads 7.7 the way a person would round it.
    return [Math]::Round([Math]::Min(10.0, [Math]::Max(0.0, $score)), 1, [System.MidpointRounding]::AwayFromZero)
}

function Get-RoleDefinitionPermission {
    <#
    .SYNOPSIS
    The permission blocks of an Azure role definition, whichever Az.Resources shape it has.
    .DESCRIPTION
    Az.Resources 10 moved Actions, NotActions, DataActions and NotDataActions off the role
    definition into a Permissions array (one block per permission set, each with an optional
    ABAC condition). Older versions flatten the single block onto the definition itself.
    This returns the blocks as uniform objects with the four string arrays so the collector
    rates a custom role the same way on either version. A pure rule; nothing here calls Azure.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]
        [AllowNull()]
        $Definition
    )

    $toArray = { param($Value) @($Value | Where-Object { $null -ne $_ -and "$_" -ne '' } | ForEach-Object { [string]$_ }) }

    $blocks = @(Get-PropertyOrDefault -InputObject $Definition -Name 'Permissions' -Default $null | Where-Object { $null -ne $_ })
    if ($blocks.Count -eq 0) { $blocks = @($Definition) }   # Az.Resources < 10: the definition is the block

    foreach ($block in $blocks) {
        [pscustomobject]@{
            Actions        = & $toArray (Get-PropertyOrDefault -InputObject $block -Name 'Actions' -Default @())
            NotActions     = & $toArray (Get-PropertyOrDefault -InputObject $block -Name 'NotActions' -Default @())
            DataActions    = & $toArray (Get-PropertyOrDefault -InputObject $block -Name 'DataActions' -Default @())
            NotDataActions = & $toArray (Get-PropertyOrDefault -InputObject $block -Name 'NotDataActions' -Default @())
        }
    }
}

function Resolve-DirectoryPrincipal {
    <#
    .SYNOPSIS
    Look up one directory object and say what it is and whether it can sign in.
    .DESCRIPTION
    Resolves users, groups and service principals through Graph, once per object id; results
    are cached in $Audit.Cache.Principals. Service principals are classified as ManagedIdentity,
    AppRegistration (an application object exists in this tenant) or EnterpriseApp. The
    activity decision itself is the pure rule Resolve-PrincipalActivity.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]
        [string]$ObjectId,

        # The audit state built by Get-RiskyRoleAssignment: Cache.Principals, Cache.Groups, Applications.
        [Parameter(Mandatory)]
        [hashtable]$Audit
    )

    if ($Audit.Cache.Principals.ContainsKey($ObjectId)) { return $Audit.Cache.Principals[$ObjectId] }

    $principal = [pscustomobject]@{
        ObjectId       = $ObjectId
        Type           = 'Unknown'
        DisplayName    = '(unresolved)'
        UPN            = $null
        AppId          = $null
        SpType         = $null
        IsEnabled      = $null
        ActivityStatus = 'Unknown'
        ActivityReason = $null
    }

    try {
        $object = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/directoryObjects/$ObjectId" -ErrorAction Stop
        $odataType = [string](Get-PropertyOrDefault -InputObject $object -Name '@odata.type' -Default '')
        $principal.DisplayName = Get-PropertyOrDefault -InputObject $object -Name 'displayName' -Default '(unnamed)'

        switch -Wildcard ($odataType) {
            '*.user' {
                $principal.Type = 'User'
                $principal.UPN = Get-PropertyOrDefault -InputObject $object -Name 'userPrincipalName' -Default $null
                # /directoryObjects does not reliably return accountEnabled; ask /users.
                try {
                    $detail = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/users/$ObjectId`?`$select=accountEnabled,userPrincipalName" -ErrorAction Stop
                    $principal.IsEnabled = Get-PropertyOrDefault -InputObject $detail -Name 'accountEnabled' -Default $null
                    $upn = Get-PropertyOrDefault -InputObject $detail -Name 'userPrincipalName' -Default $null
                    if ($upn) { $principal.UPN = $upn }
                }
                catch { Write-Verbose "Could not read user $ObjectId : $($_.Exception.Message)" }
                $activity = Resolve-PrincipalActivity -Type 'User' -AccountEnabled $principal.IsEnabled
            }
            '*.group' {
                $principal.Type = 'Group'
                $activity = Resolve-PrincipalActivity -Type 'Group'
            }
            '*.servicePrincipal' {
                $principal.AppId = Get-PropertyOrDefault -InputObject $object -Name 'appId' -Default $null
                $principal.SpType = Get-PropertyOrDefault -InputObject $object -Name 'servicePrincipalType' -Default $null
                $blocked = $null
                try {
                    $detail = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/servicePrincipals/$ObjectId`?`$select=disabledByMicrosoftStatus,accountEnabled,appId,servicePrincipalType" -ErrorAction Stop
                    $principal.IsEnabled = Get-PropertyOrDefault -InputObject $detail -Name 'accountEnabled' -Default $null
                    $blocked = Get-PropertyOrDefault -InputObject $detail -Name 'disabledByMicrosoftStatus' -Default $null
                    if (-not $principal.AppId) { $principal.AppId = Get-PropertyOrDefault -InputObject $detail -Name 'appId' -Default $null }
                    if (-not $principal.SpType) { $principal.SpType = Get-PropertyOrDefault -InputObject $detail -Name 'servicePrincipalType' -Default $null }
                }
                catch { Write-Verbose "Could not read service principal $ObjectId : $($_.Exception.Message)" }

                $appInfo = $null
                if ($principal.SpType -eq 'ManagedIdentity') { $principal.Type = 'ManagedIdentity' }
                elseif ($principal.AppId -and $Audit.Applications.ContainsKey($principal.AppId)) {
                    $principal.Type = 'AppRegistration'
                    $appInfo = $Audit.Applications[$principal.AppId]
                }
                else { $principal.Type = 'EnterpriseApp' }

                $activity = Resolve-PrincipalActivity -Type $principal.Type -AccountEnabled $principal.IsEnabled -DisabledByMicrosoftStatus $blocked -ApplicationInfo $appInfo
            }
            default {
                $principal.Type = 'Other'
                $activity = Resolve-PrincipalActivity -Type 'Other'
            }
        }
        $principal.ActivityStatus = $activity.ActivityStatus
        $principal.ActivityReason = $activity.ActivityReason
    }
    catch {
        Write-Verbose "Could not resolve $ObjectId : $($_.Exception.Message)"
    }

    $Audit.Cache.Principals[$ObjectId] = $principal
    return $principal
}

function Resolve-PrincipalActivity {
    <#
    .SYNOPSIS
    Decide whether a principal can sign in at all, and why not.
    .DESCRIPTION
    Pure rule. Returns ActivityStatus (Active, Disabled, NoValidCredential, BlockedByMicrosoft,
    Unknown) and a reason. Precedence for service principals: sign-in disabled, then blocked by
    Microsoft, then (app registrations only) deactivated or without a usable credential.
    Groups never sign in and count as Active; managed identities have no credentials to check.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]
        [ValidateSet('User', 'Group', 'ManagedIdentity', 'AppRegistration', 'EnterpriseApp', 'Other', 'Unknown')]
        [string]$Type,

        [Parameter()]
        [AllowNull()]
        [nullable[bool]]$AccountEnabled,

        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$DisabledByMicrosoftStatus,

        # For app registrations: the entry from Get-ApplicationInventory (IsDisabled,
        # CredentialCount, HasValidCredential). Null when the inventory has no entry.
        [Parameter()]
        [AllowNull()]
        $ApplicationInfo
    )

    $status = 'Unknown'
    $reason = $null

    switch ($Type) {
        'User' {
            if ($AccountEnabled -eq $false) { $status = 'Disabled'; $reason = 'Account disabled' }
            elseif ($AccountEnabled -eq $true) { $status = 'Active' }
        }
        'Group' { $status = 'Active' }
        'Unknown' { }
        'Other' { $status = 'Active' }
        default {
            if ($AccountEnabled -eq $false) {
                $status = 'Disabled'; $reason = 'Service principal sign-in disabled'
            }
            elseif ($DisabledByMicrosoftStatus) {
                $status = 'BlockedByMicrosoft'; $reason = "Blocked by Microsoft: $DisabledByMicrosoftStatus"
            }
            elseif ($Type -eq 'AppRegistration') {
                if ($null -eq $ApplicationInfo) {
                    $status = 'Unknown'; $reason = 'Could not load credential info'
                }
                elseif ([bool](Get-PropertyOrDefault -InputObject $ApplicationInfo -Name 'IsDisabled' -Default $false)) {
                    $status = 'Disabled'; $reason = 'App registration deactivated'
                }
                else {
                    $count = [int](Get-PropertyOrDefault -InputObject $ApplicationInfo -Name 'CredentialCount' -Default 0)
                    $hasValid = [bool](Get-PropertyOrDefault -InputObject $ApplicationInfo -Name 'HasValidCredential' -Default $false)
                    if ($count -eq 0) { $status = 'NoValidCredential'; $reason = 'No password or certificate credentials' }
                    elseif (-not $hasValid) { $status = 'NoValidCredential'; $reason = "All $count credentials expired" }
                    else { $status = 'Active' }
                }
            }
            else {
                $status = 'Active'
            }
        }
    }

    [pscustomobject]@{ ActivityStatus = $status; ActivityReason = $reason }
}

function Resolve-RiskyRoleAssignmentFinding {
    <#
    .SYNOPSIS
    Turn one privileged assignment plus its resolved principal into a typed finding.
    .DESCRIPTION
    Pure assembly: scope classification, score, severity, cleanup commands, a stable Id and the
    Protected flag. Nothing here calls Azure or Graph, so every rule is provable on a fixture.

    Protected means Remove-RiskyRoleAssignment will report the finding and not touch it:
      - inherited through a group (the fix is a membership or the group's assignment, both yours to decide)
      - PIM eligible or activated (managed in PIM, not by deleting an assignment)
      - a break-glass account named with -BreakGlassAccount
      - the identity running the audit
    #>
    [CmdletBinding()]
    [OutputType('RiskyRolesAnalyzer.RiskyRoleAssignment')]
    param(
        [Parameter(Mandatory)]
        [ValidateSet('Azure', 'Entra')]
        [string]$RoleScope,

        [Parameter(Mandatory)]
        [string]$RoleName,

        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$RoleDefinitionId,

        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$Scope,

        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$ScopeName,

        [Parameter(Mandatory)]
        [ValidateSet('Permanent', 'Eligible', 'Activated')]
        [string]$AssignmentType,

        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$AssignmentId,

        # Output of Resolve-DirectoryPrincipal (ObjectId, Type, DisplayName, UPN, AppId,
        # IsEnabled, ActivityStatus, ActivityReason).
        [Parameter(Mandatory)]
        $Principal,

        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$ViaGroup,

        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$ViaGroupId,

        [Parameter()]
        [bool]$IsCustomRole = $false,

        [Parameter()]
        [AllowNull()]
        [string[]]$RiskyAction,

        # UPNs or object ids that must never be removed.
        [Parameter()]
        [AllowNull()]
        [string[]]$BreakGlassAccount,

        # UPN of the identity running the audit.
        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$CurrentAccount,

        [Parameter()]
        [AllowNull()]
        $Source
    )

    $principalId = [string](Get-PropertyOrDefault -InputObject $Principal -Name 'ObjectId' -Default '')
    $principalType = [string](Get-PropertyOrDefault -InputObject $Principal -Name 'Type' -Default 'Unknown')
    $upn = Get-PropertyOrDefault -InputObject $Principal -Name 'UPN' -Default $null
    $activity = [string](Get-PropertyOrDefault -InputObject $Principal -Name 'ActivityStatus' -Default 'Unknown')
    $risky = @($RiskyAction | Where-Object { $_ })

    $scopeInfo = Resolve-RoleScope -Scope $Scope -RoleScope $RoleScope
    $score = Get-RiskyRoleScore -RoleName $RoleName -ScopeLevel $scopeInfo.Level -PrincipalType $principalType `
        -AssignmentType $AssignmentType -IsCustomRole $IsCustomRole -RiskyAction $risky -ActivityStatus $activity
    $cleanup = Get-RiskyRoleCleanupCommand -RoleScope $RoleScope -RoleName $RoleName -Scope $Scope -PrincipalId $principalId `
        -AssignmentType $AssignmentType -AssignmentId $AssignmentId -ViaGroupId $ViaGroupId

    $protectedReason = $null
    $breakGlass = @($BreakGlassAccount | Where-Object { $_ })
    if ($ViaGroupId) { $protectedReason = "Inherited through group '$ViaGroup'" }
    elseif ($AssignmentType -eq 'Eligible') { $protectedReason = 'PIM eligibility, manage it in PIM' }
    elseif ($AssignmentType -eq 'Activated') { $protectedReason = 'PIM activation, deactivate or remove the eligibility in PIM' }
    elseif ($breakGlass -and (($principalId -and $principalId -in $breakGlass) -or ($upn -and $upn -in $breakGlass))) { $protectedReason = 'Break-glass account' }
    elseif ($CurrentAccount -and $upn -and $upn -eq $CurrentAccount) { $protectedReason = 'Identity running this audit' }

    [pscustomobject]@{
        PSTypeName       = $script:TypeName.Finding
        Id               = Get-RiskyRoleFindingId -RoleScope $RoleScope -RoleName $RoleName -Scope $Scope -PrincipalId $principalId -ViaGroupId $ViaGroupId -AssignmentType $AssignmentType
        Severity         = ConvertTo-RiskyRoleSeverity -Score $score
        RiskScore        = $score
        RoleScope        = $RoleScope
        RoleName         = $RoleName
        RoleDefinitionId = $RoleDefinitionId
        IsCustomRole     = $IsCustomRole
        RiskyActions     = [string[]]$risky
        Scope            = $Scope
        ScopeName        = $ScopeName
        ScopeLevel       = $scopeInfo.Level
        ScopeDetail      = $scopeInfo.Detail
        AssignmentType   = $AssignmentType
        AssignmentId     = $AssignmentId
        PrincipalType    = $principalType
        PrincipalName    = [string](Get-PropertyOrDefault -InputObject $Principal -Name 'DisplayName' -Default '(unresolved)')
        PrincipalId      = $principalId
        UPN              = $upn
        AppId            = Get-PropertyOrDefault -InputObject $Principal -Name 'AppId' -Default $null
        AccountEnabled   = Get-PropertyOrDefault -InputObject $Principal -Name 'IsEnabled' -Default $null
        ActivityStatus   = $activity
        ActivityReason   = Get-PropertyOrDefault -InputObject $Principal -Name 'ActivityReason' -Default $null
        ViaGroup         = $ViaGroup
        ViaGroupId       = $ViaGroupId
        Protected        = [bool]$protectedReason
        ProtectedReason  = $protectedReason
        CleanupPrimary   = $cleanup.Primary
        CleanupAlt       = $cleanup.Alt
        Source           = $Source
    }
}

function Resolve-RoleScope {
    <#
    .SYNOPSIS
    Classify an assignment scope into a hierarchy level with a short display name.
    .DESCRIPTION
    Azure RBAC scopes:
      /                                                        Root
      /providers/Microsoft.Management/managementGroups/{id}    ManagementGroup
      /subscriptions/{id}                                      Subscription
      /subscriptions/{id}/resourceGroups/{name}                ResourceGroup
      /subscriptions/{id}/resourceGroups/{name}/providers/...  Resource
    Entra directory scopes:
      /                                                        Tenant
      /administrativeUnits/{id}                                AdminUnit
      /{objectId}                                              Object (application-scoped role)
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter()]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$Scope,

        [Parameter(Mandatory)]
        [ValidateSet('Azure', 'Entra')]
        [string]$RoleScope
    )

    $level, $detail = if ($RoleScope -eq 'Entra') {
        if ([string]::IsNullOrWhiteSpace($Scope) -or $Scope -eq '/') { 'Tenant', 'Tenant-wide' }
        elseif ($Scope -match '^/administrativeUnits/(.+)$') { 'AdminUnit', "Administrative unit: $($Matches[1])" }
        else { 'Object', "Object: $($Scope.TrimStart('/'))" }
    }
    else {
        if ([string]::IsNullOrWhiteSpace($Scope) -or $Scope -eq '/') { 'Root', 'Tenant root' }
        elseif ($Scope -match '^/providers/Microsoft\.Management/managementGroups/(.+)$') { 'ManagementGroup', "MG: $($Matches[1])" }
        elseif ($Scope -match '^/subscriptions/[0-9a-fA-F\-]+/resourceGroups/[^/]+/providers/.+$') { 'Resource', "Resource: $(($Scope -split '/')[-1])" }
        elseif ($Scope -match '^/subscriptions/[0-9a-fA-F\-]+/resourceGroups/([^/]+)$') { 'ResourceGroup', "RG: $($Matches[1])" }
        elseif ($Scope -match '^/subscriptions/[0-9a-fA-F\-]+$') { 'Subscription', 'Subscription' }
        else { 'Other', $Scope }
    }

    [pscustomobject]@{ Level = $level; Detail = $detail }
}

function Test-RiskyRoleActionMatch {
    <#
    .SYNOPSIS
    Wildcard-aware match of one role definition action pattern against one concrete action.
    .DESCRIPTION
    A pattern like 'Microsoft.Authorization/*' grants 'Microsoft.Authorization/roleAssignments/write'.
    '*' grants everything. Matching is case-insensitive, as ARM and Graph treat actions.
    #>
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string]$Pattern,

        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string]$Action
    )

    if ([string]::IsNullOrEmpty($Pattern) -or [string]::IsNullOrEmpty($Action)) { return $false }
    if ($Pattern -eq '*') { return $true }
    if ($Pattern -eq $Action) { return $true }
    if ($Pattern.Contains('*')) {
        $regex = '^' + [regex]::Escape($Pattern).Replace('\*', '.*') + '$'
        return [bool]($Action -match $regex)
    }
    return $false
}

function Test-RiskyRoleGraphScope {
    <#
    .SYNOPSIS
    Does the current Graph session carry every scope in the list?
    #>
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory)]
        [string[]]$Scope
    )

    $context = Get-MgContext -ErrorAction SilentlyContinue
    if (-not $context) { return $false }
    $granted = @(Get-PropertyOrDefault -InputObject $context -Name 'Scopes' -Default @())
    foreach ($required in $Scope) {
        if ($required -notin $granted) { return $false }
    }
    return $true
}

# ---- Commands (src/RiskyRolesAnalyzer/Public) ---------------------------------------------------

function Connect-RiskyRolesAnalyzer {
    <#
    .SYNOPSIS
    Sign in to Microsoft Graph and Azure with exactly the scopes the audit needs.

    .DESCRIPTION
    Connects Microsoft Graph with the read-only scopes Get-RiskyRoleAssignment uses
    (RoleManagement.Read.Directory, Directory.Read.All, Group.Read.All, Application.Read.All)
    and Azure with Connect-AzAccount for the same tenant. Sessions that already carry the scopes
    are reused. The write scope RoleManagement.ReadWrite.Directory is requested only with
    -RequestWriteScopes; Remove-RiskyRoleAssignment needs it for Entra findings, nothing else does.

    .PARAMETER TenantId
    Tenant to sign in to. Without it, the Graph sign-in picks the account's home tenant and
    Azure follows the tenant Graph ended up in.

    .PARAMETER RequestWriteScopes
    Also request RoleManagement.ReadWrite.Directory. Off by default: the audit is read-only.

    .PARAMETER SkipAzure
    Graph only. Use with Get-RiskyRoleAssignment -SkipAzure when Azure RBAC is out of scope.

    .PARAMETER UseDeviceCode
    Device code sign-in for both services, for hosts without a browser.

    .EXAMPLE
    Connect-RiskyRolesAnalyzer

    .EXAMPLE
    Connect-RiskyRolesAnalyzer -TenantId 00000000-0000-0000-0000-000000000000 -RequestWriteScopes

    .OUTPUTS
    System.Management.Automation.PSCustomObject with TenantId, GraphAccount, GraphScopes and AzureAccount.

    .NOTES
    Required permissions, read path: Graph delegated scopes RoleManagement.Read.Directory,
    Directory.Read.All, Group.Read.All and Application.Read.All, which a user consents to at sign-in;
    Azure Reader on every subscription you want to audit, or at a management group above them.
    Entra ID P2 for the PIM parts; without it Get-RiskyRoleAssignment warns once and continues.

    The write path adds RoleManagement.ReadWrite.Directory (-RequestWriteScopes) and, on the Azure
    side, Microsoft.Authorization/roleAssignments/delete on the scope.

    The Graph session lives in this PowerShell process. A new pwsh starts without it, while the Azure
    session is read back from disk, so run Connect- and Get- in the same session.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter()]
        [string]$TenantId,

        [Parameter()]
        [switch]$RequestWriteScopes,

        [Parameter()]
        [switch]$SkipAzure,

        [Parameter()]
        [switch]$UseDeviceCode
    )

    $scopes = @($script:Catalog.GraphScopes.Read)
    if ($RequestWriteScopes) { $scopes += $script:Catalog.GraphScopes.Write }

    $graph = Get-MgContext -ErrorAction SilentlyContinue
    $graphTenant = if ($graph) { [string](Get-PropertyOrDefault -InputObject $graph -Name 'TenantId' -Default '') } else { '' }
    $needsGraph = (-not $graph) -or (-not (Test-RiskyRoleGraphScope -Scope $scopes)) -or ($TenantId -and $graphTenant -ne $TenantId)
    if ($needsGraph) {
        $graphArgs = @{ Scopes = $scopes; NoWelcome = $true; ErrorAction = 'Stop' }
        if ($TenantId) { $graphArgs.TenantId = $TenantId }
        if ($UseDeviceCode) { $graphArgs.UseDeviceCode = $true }
        Write-Verbose "Connecting Microsoft Graph with scopes: $($scopes -join ', ')"
        $null = Connect-MgGraph @graphArgs
        $graph = Get-MgContext -ErrorAction Stop
    }
    $tenant = [string](Get-PropertyOrDefault -InputObject $graph -Name 'TenantId' -Default '')

    $azureAccount = $null
    if (-not $SkipAzure) {
        $azure = Get-AzContext -ErrorAction SilentlyContinue
        $azureTenant = if ($azure) { [string](Get-PropertyOrDefault -InputObject (Get-PropertyOrDefault -InputObject $azure -Name 'Tenant' -Default $null) -Name 'Id' -Default '') } else { '' }
        if (-not $azure -or ($tenant -and $azureTenant -ne $tenant)) {
            $azureArgs = @{ ErrorAction = 'Stop' }
            if ($tenant) { $azureArgs.TenantId = $tenant }
            if ($UseDeviceCode) { $azureArgs.UseDeviceCode = $true }
            Write-Verbose "Connecting Azure for tenant $tenant"
            $null = Connect-AzAccount @azureArgs
            $azure = Get-AzContext -ErrorAction Stop
        }
        $azureAccount = [string](Get-PropertyOrDefault -InputObject (Get-PropertyOrDefault -InputObject $azure -Name 'Account' -Default $null) -Name 'Id' -Default '')
    }

    [pscustomobject]@{
        TenantId     = $tenant
        GraphAccount = Get-PropertyOrDefault -InputObject $graph -Name 'Account' -Default $null
        GraphScopes  = @(Get-PropertyOrDefault -InputObject $graph -Name 'Scopes' -Default @())
        AzureAccount = $azureAccount
        WriteScope   = (Test-RiskyRoleGraphScope -Scope $script:Catalog.GraphScopes.Write)
    }
}

function Get-RiskyRoleAssignment {
    <#
    .SYNOPSIS
    Every privileged Azure RBAC and Entra ID role assignment in the tenant, scored and explained.

    .DESCRIPTION
    Read-only audit of privileged access with the blind spots posture tools tend to have:

      - custom Azure RBAC and Entra directory roles whose actions confer privilege
        (roleAssignments/write, users/password/update, denyAssignments/delete and more)
      - assignments inherited through nested groups, listed per member with the group
      - app registrations holding privileged roles with expired or no credentials
      - app registrations deactivated in the portal, service principals with sign-in disabled
        or blocked by Microsoft
      - disabled users that still hold permanent privileged assignments
      - permanent versus PIM eligible Entra assignments, scored separately

    Each finding carries a 0 to 10 risk score, a severity, the native cleanup command, and a
    Protected flag for the assignments Remove-RiskyRoleAssignment must not touch: inherited
    through a group, PIM eligible, break-glass accounts, and the identity running the audit.

    Needs an existing Microsoft Graph session with the read scopes and, unless -SkipAzure is
    set, an Az session in the same tenant. Connect-RiskyRolesAnalyzer sets both up.

    .PARAMETER SubscriptionId
    Audit only these subscriptions. Default: every enabled subscription in the tenant.

    .PARAMETER AdditionalAzureRole
    Built-in or custom Azure role names to treat as privileged on top of the catalog.

    .PARAMETER AdditionalEntraRole
    Entra directory role display names to treat as privileged on top of the catalog.

    .PARAMETER BreakGlassAccount
    User principal names or object ids of emergency access accounts. Their assignments are
    reported and marked Protected. The module cannot know which accounts these are; it warns when
    an unprotected principal is named like one.

    .PARAMETER SkipAzure
    Entra ID only; no Az session needed.

    .PARAMETER SkipEntra
    Azure RBAC only.

    .PARAMETER SkipPim
    Do not query PIM eligible assignments (tenants without Entra ID P2).

    .PARAMETER MinimumSeverity
    Return findings of this severity and above. Default: Info, which is everything.

    .EXAMPLE
    Connect-RiskyRolesAnalyzer
    Get-RiskyRoleAssignment | Format-Table

    .EXAMPLE
    Get-RiskyRoleAssignment -MinimumSeverity High -BreakGlassAccount 'breakglass@contoso.com' | Export-Csv privileged.csv

    .EXAMPLE
    Get-RiskyRoleAssignment -SkipAzure -SkipPim | Where-Object ActivityStatus -ne 'Active'

    .OUTPUTS
    RiskyRolesAnalyzer.RiskyRoleAssignment

    .NOTES
    Required permissions, read path only:
      Graph: RoleManagement.Read.Directory, Directory.Read.All, Group.Read.All, Application.Read.All
      Azure: Reader on every subscription in scope (a management group assignment works)
    #>
    [CmdletBinding()]
    [OutputType('RiskyRolesAnalyzer.RiskyRoleAssignment')]
    param(
        [Parameter()]
        [string[]]$SubscriptionId,

        [Parameter()]
        [string[]]$AdditionalAzureRole,

        [Parameter()]
        [string[]]$AdditionalEntraRole,

        [Parameter()]
        [string[]]$BreakGlassAccount,

        [Parameter()]
        [switch]$SkipAzure,

        [Parameter()]
        [switch]$SkipEntra,

        [Parameter()]
        [switch]$SkipPim,

        [Parameter()]
        [ValidateSet('Info', 'Low', 'Medium', 'High', 'Critical')]
        [string]$MinimumSeverity = 'Info'
    )

    if ($SkipAzure -and $SkipEntra) { throw 'Nothing to audit: -SkipAzure and -SkipEntra together leave no source.' }

    $graph = Get-MgContext -ErrorAction SilentlyContinue
    if (-not $graph) { throw 'Not connected to Microsoft Graph. Run Connect-RiskyRolesAnalyzer first (or Connect-MgGraph with the read scopes listed in Get-Help Get-RiskyRoleAssignment -Full).' }
    $tenantId = [string](Get-PropertyOrDefault -InputObject $graph -Name 'TenantId' -Default '')
    if (-not (Test-RiskyRoleGraphScope -Scope $script:Catalog.GraphScopes.Read)) {
        Write-Warning "The Graph session lacks one or more read scopes ($($script:Catalog.GraphScopes.Read -join ', ')). Parts of the audit may come back empty. Connect-RiskyRolesAnalyzer requests the full set."
    }

    if (-not $SkipAzure) {
        $azure = Get-AzContext -ErrorAction SilentlyContinue
        if (-not $azure) { throw 'Not connected to Azure. Run Connect-RiskyRolesAnalyzer first, or use -SkipAzure for an Entra-only audit.' }
        $azureTenant = [string](Get-PropertyOrDefault -InputObject (Get-PropertyOrDefault -InputObject $azure -Name 'Tenant' -Default $null) -Name 'Id' -Default '')
        if ($tenantId -and $azureTenant -and $azureTenant -ne $tenantId) {
            throw "Graph is signed in to tenant $tenantId but Azure to $azureTenant. Reconnect with Connect-AzAccount -TenantId $tenantId, or run Connect-RiskyRolesAnalyzer -TenantId $tenantId."
        }
    }

    $audit = @{
        TenantId             = $tenantId
        CurrentAccount       = [string](Get-PropertyOrDefault -InputObject $graph -Name 'Account' -Default '')
        BreakGlassAccount    = @($BreakGlassAccount | Where-Object { $_ })
        PrivilegedAzureRoles = @(@($script:Catalog.PrivilegedAzureRoles) + @($AdditionalAzureRole) | Where-Object { $_ } | Sort-Object -Unique)
        PrivilegedEntraRoles = @(@($script:Catalog.PrivilegedEntraRoles) + @($AdditionalEntraRole) | Where-Object { $_ } | Sort-Object -Unique)
        RiskyAzureActions    = @($script:Catalog.RiskyAzureActions)
        RiskyEntraActions    = @($script:Catalog.RiskyEntraActions)
        Applications         = @{}
        Cache                = @{ Principals = @{}; Groups = @{} }
    }
    Write-Verbose "Tenant $tenantId, $($audit.PrivilegedAzureRoles.Count) Azure and $($audit.PrivilegedEntraRoles.Count) Entra roles tracked"

    Write-Progress -Activity 'RiskyRolesAnalyzer' -Status 'Loading app registrations'
    $audit.Applications = Get-ApplicationInventory

    $findings = [System.Collections.Generic.List[object]]::new()
    if (-not $SkipAzure) { foreach ($finding in @(Get-AzureRoleFinding -Audit $audit -TenantId $tenantId -SubscriptionId $SubscriptionId)) { $findings.Add($finding) } }
    if (-not $SkipEntra) { foreach ($finding in @(Get-EntraRoleFinding -Audit $audit -SkipPim:$SkipPim)) { $findings.Add($finding) } }
    Write-Progress -Activity 'RiskyRolesAnalyzer' -Completed

    $pattern = [string]$script:Catalog.BreakGlassNamePattern
    $suspects = @($findings | Where-Object { -not $_.Protected -and ($_.PrincipalName -match $pattern -or ($_.UPN -and $_.UPN -match $pattern)) } | ForEach-Object PrincipalName | Sort-Object -Unique)
    if ($suspects.Count) {
        Write-Warning "These look like emergency access accounts and are not protected: $($suspects -join ', '). Pass -BreakGlassAccount with their UPNs or object ids so Remove-RiskyRoleAssignment refuses them."
    }

    $rank = @{ Info = 0; Low = 1; Medium = 2; High = 3; Critical = 4 }
    $minimum = $rank[$MinimumSeverity]
    Write-Verbose "$($findings.Count) finding(s) before the severity filter"
    $findings | Where-Object { $rank[$_.Severity] -ge $minimum } | Sort-Object -Property @{ Expression = 'RiskScore'; Descending = $true }, RoleScope, RoleName, PrincipalName
}

function Export-RiskyRoleReport {
    <#
    .SYNOPSIS
    Write the findings to a self-contained HTML report.

    .DESCRIPTION
    One file, no external resources, opens anywhere: summary cards, search, filters, sortable
    columns, CSV export, the native cleanup command per finding, and a checkbox per removable
    finding that builds the Remove-RiskyRoleAssignment command for your PowerShell session.
    Nothing runs from the page; it only helps you decide and copy.

    .PARAMETER InputObject
    Findings from Get-RiskyRoleAssignment.

    .PARAMETER Path
    Where to write the report. Default: ./RiskyRolesAnalyzer-report-<timestamp>.html.

    .PARAMETER Title
    Heading of the report. Default: Privileged Role Audit.

    .PARAMETER TenantId
    Shown in the header. Default: the tenant of the current Graph session.

    .PARAMETER TenantName
    Shown next to the id. Default: the organisation display name from Graph, when readable.

    .PARAMETER Open
    Open the report in the default browser after writing it.

    .EXAMPLE
    $findings = Get-RiskyRoleAssignment
    $findings | Export-RiskyRoleReport -Open

    .EXAMPLE
    Get-RiskyRoleAssignment -SkipAzure | Export-RiskyRoleReport -Path ./entra-roles.html -Title 'Contoso Entra roles'

    .OUTPUTS
    System.IO.FileInfo

    .NOTES
    Required permissions: none beyond what produced the findings. The report is rendered from the
    objects you pass in. The tenant name is looked up through Graph when a session exists and the
    organisation is readable; without it the header shows the tenant id alone.

    The file is self-contained: no external scripts, styles or fonts, nothing is sent anywhere, and
    the findings are embedded as JSON. It is safe to hand to someone outside your organisation only
    if the findings themselves are, because it contains principal names, ids and scopes.
    #>
    [CmdletBinding(SupportsShouldProcess, ConfirmImpact = 'Low')]
    [OutputType([System.IO.FileInfo])]
    param(
        [Parameter(ValueFromPipeline)]
        [AllowNull()]
        [PSTypeName('RiskyRolesAnalyzer.RiskyRoleAssignment')]
        [object[]]$InputObject,

        [Parameter()]
        [string]$Path = (Join-Path (Get-Location) ('RiskyRolesAnalyzer-report-{0:yyyyMMdd-HHmmss}.html' -f (Get-Date))),

        [Parameter()]
        [string]$Title = 'Privileged Role Audit',

        [Parameter()]
        [string]$TenantId,

        [Parameter()]
        [string]$TenantName,

        [Parameter()]
        [switch]$Open
    )

    begin {
        $items = [System.Collections.Generic.List[object]]::new()
    }

    process {
        foreach ($item in @($InputObject)) { if ($null -ne $item) { $items.Add($item) } }
    }

    end {
        if (-not $TenantId) {
            $context = Get-MgContext -ErrorAction SilentlyContinue
            $TenantId = [string](Get-PropertyOrDefault -InputObject $context -Name 'TenantId' -Default '')
        }
        if (-not $TenantName) {
            try {
                $organisation = @(Get-GraphCollection -Uri 'https://graph.microsoft.com/v1.0/organization?$select=displayName')
                if ($organisation.Count) { $TenantName = [string](Get-PropertyOrDefault -InputObject $organisation[0] -Name 'displayName' -Default '') }
            }
            catch { Write-Verbose "Organisation name not readable: $($_.Exception.Message)" }
        }
        $html = ConvertTo-RiskyRoleReportHtml -InputObject $items.ToArray() -TenantId $TenantId -TenantName $TenantName -Title $Title

        if (-not $PSCmdlet.ShouldProcess($Path, "Write HTML report with $($items.Count) finding(s)")) { return }
        Set-Content -Path $Path -Value $html -Encoding utf8 -NoNewline
        $file = Get-Item -Path $Path
        Write-Verbose "Report with $($items.Count) finding(s): $($file.FullName)"
        if ($Open) { Invoke-Item -Path $file.FullName }
        $file
    }
}

# ---- Get-RiskyRoleReportTemplate, the single-file variant ---------------------------------------
function Get-RiskyRoleReportTemplate {
    [CmdletBinding()]
    [OutputType([string])]
    param()

    return $script:ReportTemplate
}

# ================================================================================================
#  Main
# ================================================================================================

$connect = @{}
if ($TenantId) { $connect.TenantId = $TenantId }
if ($SkipAzure) { $connect.SkipAzure = $true }
if ($UseDeviceCode) { $connect.UseDeviceCode = $true }
$session = Connect-RiskyRolesAnalyzer @connect

Write-Host "Tenant $($session.TenantId)" -ForegroundColor Cyan
Write-Host "  Graph $($session.GraphAccount)" -ForegroundColor DarkGray
if ($session.AzureAccount) { Write-Host "  Azure $($session.AzureAccount)" -ForegroundColor DarkGray }

$audit = @{ MinimumSeverity = $MinimumSeverity }
foreach ($name in 'SubscriptionId', 'AdditionalAzureRole', 'AdditionalEntraRole', 'BreakGlassAccount') {
    if ($PSBoundParameters.ContainsKey($name)) { $audit[$name] = $PSBoundParameters[$name] }
}
foreach ($name in 'SkipAzure', 'SkipEntra', 'SkipPim') {
    if ($PSBoundParameters.ContainsKey($name)) { $audit[$name] = $PSBoundParameters[$name] }
}

$stopwatch = [System.Diagnostics.Stopwatch]::StartNew()
$findings = @(Get-RiskyRoleAssignment @audit)
$stopwatch.Stop()

if (-not $OutputPath) {
    $OutputPath = Join-Path (Get-Location) ('RiskyRolesAnalyzer-report-{0:yyyyMMdd-HHmmss}.html' -f (Get-Date))
}
$report = @{ Path = $OutputPath; TenantId = $session.TenantId; Confirm = $false }
if (-not $NoOpen) { $report.Open = $true }
$file = $findings | Export-RiskyRoleReport @report

Write-Host ''
Write-Host ("{0} finding(s) in {1} s" -f $findings.Count, [int]$stopwatch.Elapsed.TotalSeconds) -ForegroundColor Cyan
foreach ($group in ($findings | Group-Object Severity | Sort-Object { @{ Critical = 0; High = 1; Medium = 2; Low = 3; Info = 4 }[$_.Name] })) {
    $colour = switch ($group.Name) { 'Critical' { 'Red' } 'High' { 'Yellow' } default { 'DarkGray' } }
    Write-Host ("  {0,-9}{1}" -f $group.Name, $group.Count) -ForegroundColor $colour
}
Write-Host ''
Write-Host "Report: $($file.FullName)" -ForegroundColor Green
Write-Host 'To act on these findings instead of reading them, the module removes them with a prompt and a backup:' -ForegroundColor DarkGray
Write-Host '  Install-Module RiskyRolesAnalyzer -AllowPrerelease' -ForegroundColor DarkGray
